<?php

declare(strict_types=1);

namespace Garde\Repository;

use PDO;

/**
 * Journal des modifications (CDC EF-53, EF-54).
 *
 * Cette classe n'expose que l'écriture. Aucun écran de consultation ou de
 * gestion du journal ne fait partie de l'application.
 *
 * La garantie ne s'arrête pas là. En production, le compte applicatif ne
 * reçoit que le droit INSERT sur la table, si bien qu'une requête de mise à
 * jour écrite par mégarde ailleurs dans le code serait refusée par la base
 * (voir database/exploitation/droits-applicatifs.sql). Une règle applicative
 * seule ne protège pas d'une erreur de programmation.
 */
final class Journal
{
    public static function consigner(
        PDO $base,
        ?int $utilisateurId,
        string $login,
        string $action,
        string $typeCible,
        ?int $cibleId = null,
        ?string $valeurAvant = null,
        ?string $valeurApres = null,
    ): void {
        $base->prepare(
            'INSERT INTO journal_audit
                (utilisateur_id, login, action, type_cible, cible_id,
                 valeur_avant, valeur_apres)
             VALUES (?, ?, ?, ?, ?, ?, ?)'
        )->execute([
            $utilisateurId, $login, $action, $typeCible, $cibleId,
            $valeurAvant, $valeurApres,
        ]);
    }

}
<?php

declare(strict_types=1);

/**
 * Point d'entrée unique de l'application.
 *
 * Seul ce dossier est exposé par le serveur web : le code, la configuration,
 * les migrations et les fichiers produits sont hors du document root et ne
 * sont donc atteignables par aucune adresse.
 *
 * Ce fichier ne fait que quatre choses :
 *   1. amorcer l'autochargement et la connexion ;
 *   2. déterminer qui est connecté ;
 *   3. déclarer la table des routes ;
 *   4. émettre la réponse.
 *
 * Toute logique de page appartient à un contrôleur (src/Controller).
 */

require_once dirname(__DIR__) . '/src/autochargement.php';

use Garde\Controller\ControleurComptes;
use Garde\Controller\ControleurGarde;
use Garde\Controller\ControleurPersonnes;
use Garde\Controller\ControleurPlanning;
use Garde\Http\Gabarit;
use Garde\Http\Routeur;
use Garde\Security\Authentification;
use Garde\Support\Base;

$routeur = new Routeur();

try {
    $base = Base::connexion();
    $utilisateur = Authentification::utilisateur($base);
} catch (RuntimeException $erreur) {
    // Ni base ni identité : aucune page n'a de sens. On répond franchement
    // plutôt que d'afficher une coquille vide.
    http_response_code(503);
    header('Content-Type: text/html; charset=UTF-8');
    header('Cache-Control: no-store');
    echo Gabarit::rendre('erreurs/erreur', [
        'titre' => 'Service temporairement indisponible',
        'code' => 503,
        'message' => $erreur->getMessage() . ' Réessayez, puis contactez la DSN '
            . 'si le problème persiste.',
        'utilisateur' => null,
        'routeur' => $routeur,
        'cheminCourant' => '/',
    ]);
    exit;
}

// ---------------------------------------------------------------------
// Table des routes
//
// Chaque contrôleur déclare les siennes, avec les rôles qui y donnent accès.
// Une route sans rôle déclaré est refusée à tout le monde : l'oubli échoue
// du côté fermé (voir Routeur).
// ---------------------------------------------------------------------

(new ControleurGarde($base, $routeur))->enregistrerRoutes();
(new ControleurPlanning($base, $routeur))->enregistrerRoutes();
(new ControleurPersonnes($base, $routeur))->enregistrerRoutes();
(new ControleurComptes($base, $routeur))->enregistrerRoutes();

// ---------------------------------------------------------------------
// Traitement de la requête
// ---------------------------------------------------------------------

$chemin = parse_url((string) ($_SERVER['REQUEST_URI'] ?? '/'), PHP_URL_PATH);
$methode = (string) ($_SERVER['REQUEST_METHOD'] ?? 'GET');

$pageErreur = static function (
    int $code,
    string $titre,
    string $message,
) use ($routeur, $utilisateur, $chemin): array {
    return [
        'statut' => $code,
        'contenu' => Gabarit::rendre('erreurs/erreur', [
            'titre' => $titre,
            'code' => $code,
            'message' => $message,
            'utilisateur' => $utilisateur,
            'routeur' => $routeur,
            'cheminCourant' => is_string($chemin) ? $chemin : '/',
        ]),
    ];
};

try {
    $resultat = is_string($chemin) && $chemin !== ''
        ? $routeur->traiter($methode, $chemin, $utilisateur)
        : $pageErreur(
            400,
            'Adresse invalide',
            'L’adresse demandée n’est pas valide. Revenez à l’accueil et '
            . 'utilisez la navigation de l’application.',
        );
} catch (Throwable $exception) {
    // Le message d'origine peut contenir un chemin de fichier ou un fragment
    // de requête : il part au journal du serveur, jamais à la page.
    error_log($exception->getMessage());
    $resultat = $pageErreur(
        500,
        'Erreur interne',
        'L’opération n’a pas pu aboutir. Aucun détail technique n’est affiché ; '
        . 'réessayez puis contactez la DSN si le problème persiste.',
    );
}

http_response_code($resultat['statut']);
header('Cache-Control: no-store');

if (!isset($resultat['entetes'])) {
    header('Content-Type: text/html; charset=UTF-8');
} else {
    foreach ($resultat['entetes'] as $entete) {
        header($entete);
    }
}

echo $resultat['contenu'];

