275	    /** @return array{statut: int, contenu: string, entetes?: list<string>} */
276	    public function creer(Utilisateur $utilisateur): array
277	    {
278	        $date = $_POST['date_debut'] ?? null;
279	        // Le libellé est facultatif : absent, il est déduit du numéro de
280	        // semaine par le dépôt.
281	        $libelle = $_POST['libelle'] ?? null;
282	        $sourceTransmise = $_POST['planning_source_id'] ?? '';
283	        $planningAfficheId = $this->identifiantOption($_POST['planning_affiche_id'] ?? null);
284	        $saisie = [
285	            'date_debut' => is_string($date) ? $date : '',
286	            'libelle' => is_string($libelle) ? $libelle : '',
287	            'planning_source_id' => is_string($sourceTransmise) ? $sourceTransmise : '',
288	        ];
