509	        if ($identifiant === null) {
510	            $plannings = PlanningHebdomadaire::lister($this->base);
511	            $identifiant = $plannings === [] ? null : (int) $plannings[0]['id'];
512	        }
513	        $planning = $identifiant === null
514	            ? null
515	            : PlanningHebdomadaire::charger($this->base, $identifiant);
516	
517	        if ($planning === null) {
518	            return $this->erreur(
519	                404,
520	                'Semaine introuvable',
521	                'Cette semaine n’existe pas. Revenez au planning et choisissez '
522	                . 'une semaine disponible.',
523	                $utilisateur,
524	            );
525	        }
526	
527	        $planningId = (int) $planning['id'];
528	
529	        $directeur = $this->base->prepare(
530	            'SELECT nom, portable, heure_debut, heure_fin
531	               FROM directeur_garde WHERE planning_id = ?'
532	        );
533	        $directeur->execute([$planningId]);
534	        $directeurGarde = $directeur->fetch() ?: null;
535	
536	        $couverture = $this->base->prepare(
537	            'SELECT etablissement, ordre, jour, couverte
538	               FROM couverture_ght WHERE planning_id = ?
539	              ORDER BY ordre, etablissement, jour'
540	        );
541	        $couverture->execute([$planningId]);
542	
543	        $ght = [];
544	        foreach ($couverture->fetchAll() as $ligne) {
545	            $ght[(string) $ligne['etablissement']][(string) $ligne['jour']]
546	                = (bool) $ligne['couverte'];
547	        }
548	
549	        $pdf = PlanningPdf::produire(
