45	    /** @return list<array<string, mixed>> */
46	    public static function lister(PDO $base): array
47	    {
48	        $requete = $base->prepare(
49	            'SELECT p.id, p.date_debut, p.date_fin, p.libelle, p.statut,
50	                    p.publie_le,
51	                    (SELECT COUNT(*) FROM ligne_planning l
52	                      WHERE l.planning_id = p.id) AS nombre_lignes,
53	                    (SELECT COUNT(*)
54	                       FROM affectation_planning a
55	                       JOIN ligne_planning l ON l.id = a.ligne_planning_id
56	                      WHERE l.planning_id = p.id) AS nombre_affectations
57	               FROM planning p
58	           ORDER BY p.date_debut DESC, p.id DESC'
59	        );
60	        $requete->execute();
61	
62	        return $requete->fetchAll();
63	    }
