65	    /**
66	     * Crée une semaine et y recopie toutes les lignes du modèle.
67	     *
68	     * Le libellé est facultatif : laissé vide, il est déduit du numéro de
69	     * semaine. C'était jusqu'ici une saisie obligatoire, et une saisie que
70	     * personne ne peut faire juste du premier coup — la semaine allant du
71	     * vendredi au jeudi, elle chevauche deux numéros ISO (voir
72	     * libelleParDefaut).
73	     *
74	     * Une semaine de référence peut fournir les affectations initiales. Les
75	     * lignes sont rapprochées par leur modèle, puis chaque jour est reporté
76	     * au même rang dans la nouvelle période. Une ligne historique supprimée
77	     * du dispositif ne réapparaît donc pas dans un nouveau planning (RG-10).
78	     */
79	    public static function creer(
80	        PDO $base,
81	        Utilisateur $acteur,
82	        string $dateDebut,
83	        ?string $libelle = null,
84	        ?int $planningSourceId = null,
85	    ): int {
86	        $debut = self::date($dateDebut, 'La date de début');
87	        if ($debut->format('N') !== '5') {
88	            // Dernier verrou, et le seul qui fasse foi. L'écran ne propose
89	            // que des vendredis, mais une requête forgée n'a pas à passer
90	            // par l'écran (RG-17).
91	            throw new ErreurSaisie(
92	                'La semaine doit commencer un vendredi, et le '
93	                . self::dateLisible($debut) . ' n’en est pas un.'
94	            );
95	        }
96	        $libelle = self::texteSimple($libelle, 'Le libellé de la semaine', 120, false)
97	            ?? self::libelleParDefaut($dateDebut);
98	        $dateFin = $debut->modify('+6 days')->format('Y-m-d');
99	
100	        $base->beginTransaction();
101	        try {
102	            $source = null;
103	            if ($planningSourceId !== null) {
104	                if ($planningSourceId < 1) {
105	                    throw new ErreurSaisie('La semaine de référence est invalide.');
106	                }
107	                $requeteSource = $base->prepare(
108	                    'SELECT id, date_debut, date_fin, libelle
109	                       FROM planning
110	                      WHERE id = ?
111	                      LOCK IN SHARE MODE'
112	                );
113	                $requeteSource->execute([$planningSourceId]);
114	                $source = $requeteSource->fetch();
115	                if ($source === false) {
116	                    throw new ErreurSaisie('La semaine de référence n’existe plus.');
117	                }
118	            }
119	
120	            $base->prepare(
121	                'INSERT INTO planning (date_debut, date_fin, libelle, statut)
122	                 VALUES (?, ?, ?, ?)'
123	            )->execute([$dateDebut, $dateFin, $libelle, 'brouillon']);
124	            $id = (int) $base->lastInsertId();
125	
126	            $base->prepare(
127	                'INSERT INTO ligne_planning
128	                    (planning_id, modele_ligne_id, intitule, ordre)
129	                 SELECT ?, id, intitule, ordre
130	                   FROM modele_ligne
131	                ORDER BY ordre, id'
132	            )->execute([$id]);
133	
134	            $nombreAffectations = 0;
135	            if (is_array($source)) {
136	                $reprise = $base->prepare(
137	                    'INSERT INTO affectation_planning
138	                        (ligne_planning_id, jour, personne_id, ordre, commentaire,
139	                         heure_debut, heure_fin)
140	                     SELECT cible.id,
141	                            DATE_ADD(CAST(? AS DATE),
142	                                INTERVAL DATEDIFF(a.jour, CAST(? AS DATE)) DAY),
143	                            a.personne_id, a.ordre, a.commentaire,
144	                            a.heure_debut, a.heure_fin
145	                       FROM affectation_planning a
146	                       JOIN ligne_planning origine
147	                         ON origine.id = a.ligne_planning_id
148	                       JOIN ligne_planning cible
149	                         ON cible.planning_id = ?
150	                        AND cible.modele_ligne_id = origine.modele_ligne_id
151	                      WHERE origine.planning_id = ?
152	                        AND a.jour BETWEEN ? AND ?
153	                   ORDER BY origine.ordre, a.jour, a.ordre, a.id'
154	                );
155	                $reprise->execute([
156	                    $dateDebut,
157	                    (string) $source['date_debut'],
158	                    $id,
159	                    (int) $source['id'],
160	                    (string) $source['date_debut'],
161	                    (string) $source['date_fin'],
162	                ]);
163	                $nombreAffectations = $reprise->rowCount();
164	            }
165	
166	            Journal::consigner(
167	                $base,
168	                $acteur->id,
169	                $acteur->login,
170	                'creation_planning',
171	                'planning',
172	                $id,
173	                null,
174	                self::encoder([
175	                    'date_debut' => $dateDebut,
176	                    'date_fin' => $dateFin,
177	                    'libelle' => $libelle,
178	                    'statut' => 'brouillon',
179	                    'planning_source_id' => is_array($source)
180	                        ? (int) $source['id']
181	                        : null,
182	                    'affectations_reprises' => $nombreAffectations,
183	                ]),
184	            );
185	
186	            $base->commit();
187	            return $id;
188	        } catch (PDOException $erreur) {
189	            self::annuler($base);
190	            if ((string) $erreur->getCode() === '23000') {
191	                throw new ErreurSaisie(
192	                    'Une semaine commençant à cette date existe déjà.',
193	                    0,
194	                    $erreur,
195	                );
196	            }
197	            throw $erreur;
198	        } catch (Throwable $erreur) {
199	            self::annuler($base);
200	            throw $erreur;
201	        }
202	    }
