682	    /**
683	     * Libellé déduit d'une date de début.
684	     *
685	     * La semaine court du vendredi au jeudi (RG-17) : elle chevauche donc
686	     * deux numéros ISO. Le numéro retenu est celui du jeudi de fin, qui est
687	     * aussi celui des classeurs repris — la semaine du vendredi 24 juillet
688	     * 2026 y est numérotée 31, alors que le 24 juillet est en semaine ISO
689	     * 30. Demander ce numéro à la saisie revenait à demander à quelqu'un de
690	     * refaire ce calcul de tête chaque vendredi.
691	     */
692	    public static function libelleParDefaut(string $dateDebut): string
693	    {
694	        $fin = self::date($dateDebut, 'La date de début')->modify('+6 days');
695	
696	        return 'Semaine ' . $fin->format('W') . '-' . $fin->format('o');
697	    }
698	
699	    /**
700	     * Période en toutes lettres : « du vendredi 21 au jeudi 27 août 2026 ».
701	     *
702	     * Le mois et l'année ne sont répétés que lorsque la semaine les
703	     * enjambe. Une liste de semaines écrite en ISO — « 2026-08-21 au
704	     * 2026-08-27 » — se lit chiffre par chiffre ; celle-ci se lit d'un coup
705	     * d'œil, ce qui est le point : on choisit une semaine, on ne déchiffre
706	     * pas une date.
707	     */
708	    public static function periodeLisible(string $dateDebut, string $dateFin): string
709	    {
710	        $debut = self::date($dateDebut, 'La date de début');
711	        $fin = self::date($dateFin, 'La date de fin');
712	
713	        $memeAnnee = $debut->format('Y') === $fin->format('Y');
714	        $memeMois = $memeAnnee && $debut->format('n') === $fin->format('n');
715	
716	        return 'du ' . self::dateLisible($debut, !$memeMois, !$memeAnnee)
717	            . ' au ' . self::dateLisible($fin);
718	    }
719	
720	    /**
721	     * Vendredis proposés à la création, avec l'état de chacun.
722	     *
723	     * Renvoyer la liste des semaines occupées avec les semaines libres
724	     * permet à l'écran de désigner les premières sans les rendre
725	     * choisissables : le doublon n'est plus une erreur qu'on découvre après
726	     * avoir validé, c'est une option qu'on ne peut pas prendre.
727	     *
728	     * @return list<array{date: string, periode: string, libelle_defaut: string,
729	     *                    debut_court: string, fin_court: string,
730	     *                    planning_id: int|null, statut: string|null,
731	     *                    ecart: int}>
732	     */
733	    public static function vendredisProposes(PDO $base): array
734	    {
735	        $reference = new DateTimeImmutable(self::vendrediCourant());
736	        $premier = $reference->modify('-' . (self::SEMAINES_AVANT * 7) . ' days');
737	        $dernier = $reference->modify('+' . (self::SEMAINES_APRES * 7) . ' days');
738	
739	        $requete = $base->prepare(
740	            'SELECT date_debut, id, statut
741	               FROM planning
742	              WHERE date_debut BETWEEN ? AND ?'
743	        );
744	        $requete->execute([
745	            $premier->format('Y-m-d'),
746	            $dernier->format('Y-m-d'),
747	        ]);
748	
749	        $occupes = [];
750	        foreach ($requete->fetchAll() as $ligne) {
751	            $occupes[(string) $ligne['date_debut']] = [
752	                'id' => (int) $ligne['id'],
753	                'statut' => (string) $ligne['statut'],
754	            ];
755	        }
756	
757	        $vendredis = [];
758	        for ($semaine = -self::SEMAINES_AVANT; $semaine <= self::SEMAINES_APRES; $semaine++) {
759	            $debut = $reference->modify(($semaine * 7) . ' days');
760	            $fin = $debut->modify('+6 days');
761	            $date = $debut->format('Y-m-d');
762	            $existant = $occupes[$date] ?? null;
763	
764	            $vendredis[] = [
765	                'date' => $date,
766	                'periode' => self::periodeLisible(
767	                    $date,
768	                    $fin->format('Y-m-d'),
769	                ),
770	                'libelle_defaut' => self::libelleParDefaut($date),
771	                'debut_court' => self::dateCourte($debut),
772	                'fin_court' => self::dateCourte($fin),
773	                'planning_id' => $existant['id'] ?? null,
774	                'statut' => $existant['statut'] ?? null,
775	                'ecart' => $semaine,
776	            ];
777	        }
778	
779	        return $vendredis;
780	    }
