782	    private static function dateCourte(DateTimeImmutable $date): string
783	    {
784	        $jour = (int) $date->format('j');
785	
786	        return ($jour === 1 ? '1er' : (string) $jour)
787	            . ' ' . self::MOIS[(int) $date->format('n')];
788	    }
789	
790	    /**
791	     * Date en toutes lettres. Le mois et l'année ne sont écrits que
792	     * lorsqu'on les demande, pour ne pas les répéter dans une période.
793	     */
794	    private static function dateLisible(
795	        DateTimeImmutable $date,
796	        bool $avecMois = true,
797	        bool $avecAnnee = true,
798	    ): string {
799	        $jour = (int) $date->format('j');
800	
801	        return self::JOURS[(int) $date->format('N')]
802	            . ' ' . ($jour === 1 ? '1er' : (string) $jour)
803	            . ($avecMois ? ' ' . self::MOIS[(int) $date->format('n')] : '')
804	            . ($avecAnnee ? ' ' . $date->format('Y') : '');
805	    }
