807	    /** @return list<array{date: string, libelle: string, court: string}> */
808	    private static function joursPlanning(string $dateDebut): array
809	    {
810	        $debut = new DateTimeImmutable($dateDebut);
811	        $jours = [];
812	        for ($i = 0; $i < 7; $i++) {
813	            $date = $debut->modify('+' . $i . ' days');
814	            $nom = self::JOURS[(int) $date->format('N')];
815	            $jours[] = [
816	                'date' => $date->format('Y-m-d'),
817	                'libelle' => ucfirst($nom) . ' ' . $date->format('j') . ' '
818	                    . self::MOIS[(int) $date->format('n')],
819	                'court' => ucfirst($nom) . '-' . $date->format('d'),
820	            ];
821	        }
822	
823	        return $jours;
824	    }
