910	    {
911	        $valeur = str_replace(["\r\n", "\r"], "\n", $valeur);
912	        $lignes = array_map(
913	            static fn(string $ligne): string => preg_replace('/[ \t]+/u', ' ', trim($ligne)) ?? '',
914	            explode("\n", $valeur),
915	        );
916	        while ($lignes !== [] && $lignes[0] === '') {
917	            array_shift($lignes);
918	        }
919	        while ($lignes !== [] && $lignes[array_key_last($lignes)] === '') {
920	            array_pop($lignes);
921	        }
922	        $texte = implode("\n", $lignes);
923	        if ($texte === '') {
