/* =====================================================================
 * Tableau des gardes et astreintes — Centre Hospitalier de Laval
 *
 * CSS natif, sans dépendance ni outil de construction (CDC § 10).
 *
 * EX-01 — interface sobre et dense, sans élément décoratif. La priorité
 *         visuelle va aux noms de personnes et aux numéros de téléphone,
 *         jamais au nom de l'application ni à l'habillage.
 * EX-05 — de 1 280 px à un écran mural, et sur tablette. Valide jusqu'à
 *         200 % de zoom sans défilement horizontal.
 * EX-08 — contraste minimum 4,5:1, 7:1 sur l'écran du standard.
 * EX-10 — aucune information portée par la couleur seule.
 *
 * ---------------------------------------------------------------------
 * Échelle d'espacement
 *
 * Quatre pas, plus un pas fin. Chaque valeur a un rôle, et un seul :
 * l'application comptait vingt-quatre valeurs différentes pour ces cinq
 * usages, ce qui produisait des marges irrégulières d'une page à l'autre.
 *
 *   --pas-fin      colle deux éléments qui se lisent d'un seul tenant
 *                  (libellé et champ, nom et numéro)
 *   --pas-court    sépare des éléments d'un même groupe
 *   --pas          sépare deux groupes (deux champs, deux blocs)
 *   --pas-long     sépare deux sections d'une page
 *   --pas-section  sépare deux grands ensembles
 *
 * Les valeurs en dehors de cette échelle sont des dimensions, pas des
 * espacements : hauteurs de contrôle, largeurs de colonne, filets.
 *
 * ---------------------------------------------------------------------
 * Échelle typographique
 *
 * Même raisonnement que l'espacement, appliqué au texte. La feuille
 * comptait vingt-et-une tailles distinctes — 0,85 / 0,88 / 0,9 / 0,95 /
 * 1,05 / 1,1 / 1,15 / 1,25 / 1,3 / 1,35 rem — pour six usages réels. Des
 * écarts d'un dixième de rem ne se lisent pas comme une hiérarchie : ils
 * se lisent comme un défaut d'alignement.
 *
 *   --texte-xs     mention, étiquette d'état
 *   --texte-s      texte secondaire, en-tête de colonne, aide
 *   --texte-m      texte courant
 *   --texte-l      sous-titre, champ de recherche principal
 *   --texte-xl     titre de section, nom d'une personne de garde
 *   --texte-xxl    titre de page
 *
 * Deux tailles d'affichage restent à part : ce ne sont pas des niveaux de
 * hiérarchie mais des dimensions de lecture à distance (CDC § 5.3).
 * ===================================================================== */

:root {
    color-scheme: light;

    /* La police du système : Segoe UI Variable sur les postes Windows du
     * CH, San Francisco sur macOS, la police d'interface de la
     * distribution sous Linux. Aucun fichier n'est téléchargé, donc aucun
     * saut de rendu et aucune requête réseau — un poste isolé de
     * l'intranet affiche la même chose. Arial reste en dernier recours. */
    --police: system-ui, "Segoe UI", Roboto, "Helvetica Neue", Arial,
              sans-serif;

    --texte-xs: 0.75rem;
    --texte-s: 0.875rem;
    --texte-m: 0.9375rem;
    --texte-l: 1.0625rem;
    --texte-xl: 1.25rem;
    --texte-xxl: 1.625rem;

    /* Tailles d'affichage : lues à deux ou trois mètres, elles suivent la
     * largeur de la fenêtre et non l'échelle. */
    --texte-heure: clamp(2rem, 5vw, 3.2rem);
    --texte-numero: clamp(1.5rem, 2.4vw, 1.9rem);

    --fond: #f5fafe;
    --fond-elevation: #ffffff;
    --fond-secondaire: #eff4f8;
    --fond-conteneur: #e9eef2;
    --fond-actif: #bfe9ff;
    --accent: #00b5e2;
    --texte: #1a1c1e;
    --texte-secondaire: #43474e;
    --bordure: #73777f;
    /* Filet intérieur des tableaux et des listes : plus léger que la
     * bordure principale, pour que la structure se lise sans que la grille
     * ne domine le contenu. Reste à 3,41:1 sur blanc — WCAG 1.4.11 exige
     * 3:1 pour les limites d'un composant d'interface, un filet plus clair
     * ne serait plus perceptible par tous. */
    --bordure-fine: #bcc8cf;
    --action: #006782;
    --action-survol: #004d62;
    --focus: #000000;
    --confirmation: #1f6b35;
    --erreur: #a41515;
    --avertissement: #8d4f00;

    --pas-fin: 0.25rem;
    --pas-court: 0.5rem;
    --pas: 1rem;
    --pas-long: 1.5rem;
    --pas-section: 2.5rem;

    /* Un seul rembourrage de contrôle : boutons, champs et liens-boutons
     * s'alignent alors sur la même hauteur quand ils sont côte à côte. */
    --controle-vertical: 0.5rem;
    --controle-horizontal: 0.85rem;
    --controle-bordure: 2px;

    /* Deux rayons, appliqués partout ou nulle part. Les angles étaient
     * arrondis à 0,12 rem sur les champs et 0,15 rem sur les boutons —
     * deux valeurs distinctes, toutes deux trop faibles pour se voir, et
     * rien ailleurs. Un rayon franc sur les contrôles, un rayon plus large
     * sur les blocs qui les contiennent : c'est la règle habituelle, le
     * conteneur ne doit pas paraître plus coupant que son contenu. */
    --rayon-controle: 0.25rem;
    --rayon-bloc: 0.5rem;
}

