/* =====================================================================
 * Refonte « Précision Clinique »
 *
 * Le système visuel vient des maquettes Stitch, adapté aux contraintes de
 * l'intranet : aucune ressource distante, une seule navigation, et les vrais
 * tableaux métier restent la structure de référence.
 * ===================================================================== */

body {
    background: var(--fond);
    color: var(--texte);
    font-size: var(--texte-m);
}

.coquille-application {
    display: grid;
    grid-template-columns: 14.5rem minmax(0, 1fr);
    min-height: 100vh;
}

.barre-laterale {
    background: var(--fond-conteneur);
    border-right: 1px solid var(--bordure-fine);
    display: flex;
    flex-direction: column;
    height: 100vh;
    padding: var(--pas-long) var(--pas);
    position: sticky;
    top: 0;
    z-index: 20;
}

.marque-application {
    color: var(--texte);
    display: grid;
    gap: 0.65rem;
    margin-bottom: var(--pas-long);
    padding: 0.25rem 0.35rem var(--pas);
    text-decoration: none;
}

.marque-application:hover {
    color: var(--texte);
}

.marque-application img {
    height: auto;
    max-width: 10.75rem;
    mix-blend-mode: multiply;
    width: 100%;
}

.marque-application span {
    color: var(--action);
    font-size: var(--texte-l);
    font-weight: 700;
}

.navigation {
    border: 0;
    margin: 0;
    max-width: none;
    padding: 0;
}

.navigation ul {
    display: grid;
    gap: 0.25rem;
    margin: 0;
    padding: 0;
}

.navigation a {
    align-items: center;
    border-left: 0.25rem solid transparent;
    border-radius: var(--rayon-controle);
    color: var(--texte-secondaire);
    display: flex;
    gap: 0.75rem;
    min-height: 2.75rem;
    padding: 0.55rem 0.7rem;
    text-decoration: none;
}

.navigation a:hover {
    background: var(--fond-secondaire);
    color: var(--texte);
}

.navigation a[aria-current="page"] {
    background: var(--fond-actif);
    border-left-color: var(--action);
    color: #003847;
    font-weight: 700;
    text-decoration: none;
}

.icone-navigation {
    display: inline-flex;
    flex: 0 0 1.25rem;
}

.icone-navigation svg {
    fill: none;
    height: 1.25rem;
    stroke: currentcolor;
    stroke-linecap: round;
    stroke-linejoin: round;
    stroke-width: 1.8;
    width: 1.25rem;
}

.profil-lateral {
    border-top: 1px solid var(--bordure-fine);
    margin-top: auto;
    padding: var(--pas) 0.7rem 0;
}

.profil-lateral p {
    margin: 0;
}

.profil-lateral .identite {
    color: var(--texte);
    display: grid;
    gap: 0.1rem;
    text-align: left;
}

.profil-lateral .identite span,
.roles-utilisateur {
    color: var(--texte-secondaire);
    font-size: var(--texte-xs);
}

.roles-utilisateur {
    margin-top: var(--pas-fin) !important;
}

.zone-application {
    min-width: 0;
}

.barre-superieure {
    align-items: center;
    background: var(--fond-elevation);
    border-bottom: 1px solid var(--bordure-fine);
    display: flex;
    gap: var(--pas);
    justify-content: space-between;
    min-height: 3.75rem;
    padding: 0.6rem clamp(1rem, 2.5vw, 2rem);
    position: sticky;
    top: 0;
    z-index: 15;
}

.nom-application {
    color: var(--action);
