input.content:
/* =====================================================================
 * Application shell
 *
 * Les gris de texte secondaire sont réglés au plus clair qui tienne
 * 4,5:1 sur leur fond (EX-08) : plus clairs, ils ne se liraient plus sur
 * un écran de standard mal réglé ou par un agent malvoyant.
 * ===================================================================== */

body {
    background: #f6f7f8;
}


/* ---------------------------------------------------------------------
 * Structure
 * --------------------------------------------------------------------- */

.coquille-application {
    display: grid;
    grid-template-columns: 15.25rem minmax(0, 1fr);
    min-height: 100vh;
}


/* =====================================================================
 * Sidebar
 * ===================================================================== */

.barre-laterale {
    background: #fafbfc;
    border-right: 1px solid #e2e5e8;

    display: flex;
    flex-direction: column;

    height: 100vh;

    padding: 1.15rem 0.85rem;

    position: sticky;
    top: 0;

    z-index: 20;
}


/* ---------------------------------------------------------------------
 * Marque
 * --------------------------------------------------------------------- */

.marque-application {
    color: inherit;
    display: block;

    margin: 0 0 1.7rem;

    padding: 0.2rem 0.55rem;

    text-decoration: none;
}

.marque-application:hover {
    color: inherit;
}

.marque-application img {
    display: block;

    height: auto;

    margin-bottom: 0.65rem;

    max-width: 9.25rem;

    mix-blend-mode: multiply;

    width: 100%;
}

.marque-application span {
    color: #30343a;

    display: block;

    font-size: 0.8rem;
    font-weight: 650;

    letter-spacing: -0.005em;
}


/* =====================================================================
 * Navigation
 * ===================================================================== */

.navigation {
    border: 0;

    margin: 0;

    max-width: none;

    padding: 0;
}

.navigation ul {
    display: grid;

    gap: 0.18rem;

    list-style: none;

    margin: 0;

    padding: 0;
}


/* ---------------------------------------------------------------------
 * Item
 * --------------------------------------------------------------------- */

.navigation a {
    align-items: center;

    border: 1px solid transparent;
    border-radius: 0.4rem;

    color: #586169;

    display: flex;

    font-size: 0.825rem;
    font-weight: 500;

    gap: 0.65rem;

    min-height: 2.45rem;

    padding: 0.48rem 0.6rem;

    text-decoration: none;

    transition:
        background-color 100ms ease,
        border-color 100ms ease,
        color 100ms ease;
}


/* Hover */

.navigation a:hover {
    background: #f0f2f3;

    color: #24282c;
}


/* Actif */

.navigation a[aria-current="page"] {
    background: #ffffff;

    border-color: #dfe3e5;

    box-shadow:
        0 1px 2px rgb(0 0 0 / 3%);

    color: #202428;

    font-weight: 620;

    text-decoration: none;
}


/* Petite indication accent */

.navigation a[aria-current="page"]::before {
    background: var(--action);

    border-radius: 0 1rem 1rem 0;

    content: "";

    height: 1.1rem;

    left: -0.86rem;

    position: absolute;

    width: 0.18rem;
}

.navigation li {
    position: relative;
}


/* ---------------------------------------------------------------------
 * Icônes
 * --------------------------------------------------------------------- */

.icone-navigation {
    align-items: center;

    color: #7b848b;

    display: inline-flex;

    flex: 0 0 1.15rem;

    justify-content: center;
}

.icone-navigation svg {
    fill: none;

    height: 1.05rem;

    stroke: currentcolor;
    stroke-linecap: round;
    stroke-linejoin: round;

    stroke-width: 1.7;

    width: 1.05rem;
}

.navigation a:hover .icone-navigation {
    color: #4d555b;
}

.navigation a[aria-current="page"] .icone-navigation {
    color: var(--action);
}


/* =====================================================================
 * Section administration
 * ===================================================================== */

.navigation-section {
    border-top: 1px solid #e5e8ea;

    margin-top: 1.35rem;

    padding-top: 1.15rem;
}

.navigation-section-titre {
    color: #707479;

    font-size: 0.65rem;
    font-weight: 650;

    letter-spacing: 0.055em;

    margin: 0 0 0.45rem;

    padding-inline: 0.6rem;

    text-transform: uppercase;
}


/* =====================================================================
 * Profil
 * ===================================================================== */

.profil-lateral {
    border-top: 1px solid #e2e5e8;

    margin-top: auto;

    padding: 0.9rem 0.55rem 0;
}

.profil-informations {
    display: grid;

    gap: 0.08rem;

    min-width: 0;
}

.profil-informations strong {
    color: #30353a;

    font-size: 0.78rem;
    font-weight: 620;

    overflow: hidden;

    text-overflow: ellipsis;

    white-space: nowrap;
}

.profil-login {
    color: #6f7579;

    font-size: 0.68rem;

    overflow: hidden;

    text-overflow: ellipsis;

    white-space: nowrap;
}

.profil-role {
    color: #6d757c;

    font-size: 0.69rem;

    margin-top: 0.25rem;
}


/* =====================================================================
 * Zone principale
 * ===================================================================== */

.zone-application {
    background: #f7f8f9;

    min-width: 0;
}


/* =====================================================================
 * Topbar
 * ===================================================================== */

.barre-superieure {
    align-items: center;

    backdrop-filter: blur(12px);

    background: rgb(255 255 255 / 92%);

    border-bottom: 1px solid #e4e7e9;

    display: flex;

    gap: 1rem;

    justify-content: space-between;

    min-height: 3.6rem;

    padding: 0 1.75rem;

    position: sticky;

    top: 0;

    z-index: 15;
}


/* ---------------------------------------------------------------------
 * Breadcrumb
 * --------------------------------------------------------------------- */

.barre-superieure-contexte {
    align-items: center;

    color: #72777b;

    display: flex;

    font-size: 0.74rem;

    gap: 0.5rem;
}

.barre-superieure-contexte strong {
    color: #4e565d;

    font-weight: 550;
}


/* =====================================================================
 * Session
 * ===================================================================== */

.session-utilisateur {
    align-items: center;

    display: flex;

    gap: 0.85rem;
}

.session-utilisateur > span {
    color: #6f777e;

    display: block;

    font-size: 0.73rem;
}


/* ---------------------------------------------------------------------
 * Déconnexion
 * --------------------------------------------------------------------- */

.deconnexion {
    align-items: center;

    background: #ffffff;

    border: 1px solid #d7dcdf;
    border-radius: 0.35rem;

    color: #444b50;

    display: inline-flex;

    font-size: 0.73rem;
    font-weight: 550;

    margin: 0;

    min-height: 2rem;

    padding: 0.34rem 0.65rem;

    text-decoration: none;

    transition:
        background-color 100ms ease,
        border-color 100ms ease;
}

.deconnexion:hover {
    background: #f5f6f7;

    border-color: #bdc5c9;

    color: #202428;
}


/* =====================================================================
 * Main
 * ===================================================================== */

.zone-application main {
    margin: 0;

    max-width: none;

    padding:
        1.85rem
        clamp(1.25rem, 2.6vw, 2.6rem)
        4rem;

    width: 100%;
}


/* ---------------------------------------------------------------------
 * En-tête de page
 * --------------------------------------------------------------------- */

.entete-page {
    margin-bottom: 1.65rem;
}

.entete-page h1 {
    color: #191c20;

    font-size: 1.55rem;

    font-weight: 680;

    letter-spacing: -0.032em;

    line-height: 1.2;

    margin: 0;
}

