    font-size: 0.65rem;
    font-weight: 650;

    letter-spacing: 0.055em;

    margin: 0 0 0.45rem;

    padding-inline: 0.6rem;

    text-transform: uppercase;
}


/* =====================================================================
 * Profil
 * ===================================================================== */

.profil-lateral {
    border-top: 1px solid #e2e5e8;

    margin-top: auto;

    padding: 0.9rem 0.55rem 0;
}

.profil-informations {
    display: grid;

    gap: 0.08rem;

    min-width: 0;
}

.profil-informations strong {
    color: #30353a;

    font-size: 0.78rem;
    font-weight: 620;

    overflow: hidden;

    text-overflow: ellipsis;

    white-space: nowrap;
}

.profil-login {
    color: #6f7579;

    font-size: 0.68rem;

    overflow: hidden;

    text-overflow: ellipsis;

    white-space: nowrap;
}

.profil-role {
    color: #6d757c;

    font-size: 0.69rem;

    margin-top: 0.25rem;
}


/* =====================================================================
 * Zone principale
 * ===================================================================== */

.zone-application {
    background: #f7f8f9;

    min-width: 0;
}


/* =====================================================================
 * Topbar
 * ===================================================================== */

.barre-superieure {
    align-items: center;

    backdrop-filter: blur(12px);

    background: rgb(255 255 255 / 92%);

    border-bottom: 1px solid #e4e7e9;

    display: flex;

    gap: 1rem;

    justify-content: space-between;

    min-height: 3.6rem;

    padding: 0 1.75rem;

    position: sticky;

    top: 0;

    z-index: 15;
}


/* ---------------------------------------------------------------------
 * Breadcrumb
 * --------------------------------------------------------------------- */

.barre-superieure-contexte {
    align-items: center;

    color: #72777b;

    display: flex;

    font-size: 0.74rem;

    gap: 0.5rem;
}

.barre-superieure-contexte strong {
    color: #4e565d;

    font-weight: 550;
}


/* =====================================================================
 * Session
 * ===================================================================== */

.session-utilisateur {
    align-items: center;

    display: flex;

    gap: 0.85rem;
}

.session-utilisateur > span {
    color: #6f777e;

    display: block;

    font-size: 0.73rem;
}


/* ---------------------------------------------------------------------
 * Déconnexion
 * --------------------------------------------------------------------- */

.deconnexion {
    align-items: center;

    background: #ffffff;

    border: 1px solid #d7dcdf;
    border-radius: 0.35rem;

    color: #444b50;

    display: inline-flex;

    font-size: 0.73rem;
    font-weight: 550;

    margin: 0;

    min-height: 2rem;

    padding: 0.34rem 0.65rem;

    text-decoration: none;

    transition:
        background-color 100ms ease,
        border-color 100ms ease;
}

.deconnexion:hover {
    background: #f5f6f7;

    border-color: #bdc5c9;

    color: #202428;
}


/* =====================================================================
 * Main
 * ===================================================================== */

.zone-application main {
    margin: 0;

    max-width: none;

    padding:
        1.85rem
        clamp(1.25rem, 2.6vw, 2.6rem)
        4rem;

    width: 100%;
}


/* ---------------------------------------------------------------------
 * En-tête de page
 * --------------------------------------------------------------------- */

.entete-page {
    margin-bottom: 1.65rem;
}

.entete-page h1 {
    color: #191c20;

    font-size: 1.55rem;

    font-weight: 680;

    letter-spacing: -0.032em;

    line-height: 1.2;

    margin: 0;
}

