// Menu du compte. L'ouverture et la fermeture sont assurées par <details>,
// sans script ; ce module ajoute seulement ce qu'on attend d'un menu
// déroulant : Échap le referme en rendant le focus au déclencheur, un clic
// ailleurs le referme sans voler le focus.

for (const menu of document.querySelectorAll('[data-menu-profil]')) {
  if (!(menu instanceof HTMLDetailsElement)) {
    continue;
  }

  const declencheur = menu.querySelector('summary');

  menu.addEventListener('keydown', (evenement) => {
    if (evenement.key === 'Escape' && menu.open) {
      menu.open = false;
      declencheur?.focus();
    }
  });

  document.addEventListener('click', (evenement) => {
    if (menu.open && !menu.contains(evenement.target)) {
      menu.open = false;
    }
  });
}

