/* =====================================================================
 * Menu du compte
 *
 * Le bouton de déconnexion vit ici, et non plus dans la barre supérieure :
 * c'est une action rare, qui n'a pas à rester en permanence sous les yeux
 * d'un agent du standard.
 * ===================================================================== */

.menu-profil {
    border-top: 1px solid #e2e5e8;

    margin-top: auto;

    padding-top: 0.7rem;

    position: relative;
}


/* ---------------------------------------------------------------------
 * Déclencheur
 * --------------------------------------------------------------------- */

.menu-profil-declencheur {
    align-items: center;

    border-radius: 0.45rem;

    cursor: pointer;

    display: flex;

    gap: 0.65rem;

    list-style: none;

    padding: 0.45rem 0.55rem;

    transition: background-color 100ms ease;
}

.menu-profil-declencheur::-webkit-details-marker {
    display: none;
}

.menu-profil-declencheur:hover,
.menu-profil[open] > .menu-profil-declencheur {
    background: #f0f2f3;
}


/* ---------------------------------------------------------------------
 * Avatar et identité
 * --------------------------------------------------------------------- */

.avatar {
    align-items: center;

    background: var(--action);
    border-radius: 50%;

    color: #ffffff;

    display: inline-flex;

    flex: 0 0 2rem;

    font-size: 0.72rem;
    font-weight: 650;

    height: 2rem;

    justify-content: center;

    letter-spacing: 0.02em;
}

.menu-profil-identite {
    display: grid;

    flex: 1 1 auto;

    gap: 0.05rem;

    min-width: 0;
}

.menu-profil-identite strong {
    color: #30353a;

    font-size: 0.8rem;
    font-weight: 620;

    overflow: hidden;

    text-overflow: ellipsis;

    white-space: nowrap;
}

.menu-profil-identite span {
    color: #6d757c;

    font-size: 0.69rem;

    overflow: hidden;

    text-overflow: ellipsis;

    white-space: nowrap;
}

.menu-profil-chevron {
    fill: none;

    flex: 0 0 1rem;

    height: 1rem;

    stroke: #6f777e;
    stroke-linecap: round;
    stroke-linejoin: round;
    stroke-width: 2;

    transition: transform 150ms ease;

    width: 1rem;
}

.menu-profil[open] .menu-profil-chevron {
    transform: rotate(180deg);
}


/* ---------------------------------------------------------------------
 * Panneau
 * --------------------------------------------------------------------- */

.menu-profil-panneau {
    background: #ffffff;

    border: 1px solid #e1e5e8;
    border-radius: 0.6rem;

    bottom: calc(100% + 0.4rem);

    box-shadow:
        0 8px 24px rgb(0 0 0 / 10%),
        0 1px 2px rgb(0 0 0 / 4%);

    left: 0;

    padding: 0.4rem;

    position: absolute;

    right: 0;

    z-index: 30;
}

.menu-profil-entete {
    align-items: center;

    border-bottom: 1px solid #eceff1;

    display: flex;

    gap: 0.65rem;

    margin-bottom: 0.35rem;

    padding: 0.55rem 0.5rem 0.7rem;
}

.menu-profil-titre {
    color: #707479;

    font-size: 0.65rem;
    font-weight: 650;

    letter-spacing: 0.055em;

    margin: 0;

    padding: 0.45rem 0.5rem 0.25rem;

    text-transform: uppercase;
}

.menu-profil-roles {
    list-style: none;

    margin: 0;

    padding: 0;
}

.menu-profil-roles li,
.menu-profil-vide {
    color: #3b4147;

    font-size: 0.78rem;

    margin: 0;

    padding: 0.3rem 0.5rem;
}


/* ---------------------------------------------------------------------
 * Action
 * --------------------------------------------------------------------- */

.menu-profil-action {
    align-items: center;

    border-radius: 0.4rem;

    color: #30353a;

    display: flex;

    font-size: 0.8rem;
    font-weight: 550;

    gap: 0.6rem;

    margin-top: 0.75rem;

    min-height: 2.35rem;

    padding: 0.45rem 0.5rem;

    position: relative;

    text-decoration: none;

    transition: background-color 100ms ease;
}

/* Séparateur au-dessus de l'action, hors de sa zone de survol. */
.menu-profil-action::before {
    border-top: 1px solid #eceff1;

    content: "";

    left: 0.1rem;

    position: absolute;

    right: 0.1rem;

    top: -0.4rem;
}

.menu-profil-action:hover {
    background: #f3f5f6;

    color: #202428;
}

.menu-profil-action svg {
    fill: none;

    height: 1rem;

    stroke: currentcolor;
    stroke-linecap: round;
    stroke-linejoin: round;
    stroke-width: 1.8;

    width: 1rem;
}

