/* =====================================================================
 * Menu du compte
 *
 * Le bouton de déconnexion vit ici, et non plus dans la barre supérieure :
 * c'est une action rare, qui n'a pas à rester en permanence sous les yeux
 * d'un agent du standard.
 * ===================================================================== */

.menu-profil {
    border-top: 1px solid #e2e5e8;

    margin-top: auto;

    padding-top: 0.7rem;

    position: relative;
}


/* ---------------------------------------------------------------------
 * Déclencheur
 * --------------------------------------------------------------------- */

.menu-profil-declencheur {
    align-items: center;

    border-radius: 0.45rem;

    cursor: pointer;

    display: flex;

    gap: 0.65rem;

    list-style: none;

    padding: 0.45rem 0.55rem;

    transition: background-color 100ms ease;
}

.menu-profil-declencheur::-webkit-details-marker {
    display: none;
}

.menu-profil-declencheur:hover,
.menu-profil[open] > .menu-profil-declencheur {
    background: #f0f2f3;
}


/* ---------------------------------------------------------------------
 * Avatar et identité
 * --------------------------------------------------------------------- */

.avatar {
    align-items: center;

    background: var(--action);
    border-radius: 50%;

    color: #ffffff;

    display: inline-flex;

    flex: 0 0 2rem;

    font-size: 0.72rem;
    font-weight: 650;

    height: 2rem;

    justify-content: center;

    letter-spacing: 0.02em;
}

.menu-profil-identite {
    display: grid;

    flex: 1 1 auto;

    gap: 0.05rem;

    min-width: 0;
}

.menu-profil-identite strong {
    color: #30353a;

    font-size: 0.8rem;
    font-weight: 620;

    overflow: hidden;

    text-overflow: ellipsis;

    white-space: nowrap;
}

.menu-profil-identite span {
    color: #6d757c;

    font-size: 0.69rem;

    overflow: hidden;

    text-overflow: ellipsis;

    white-space: nowrap;
}

.menu-profil-chevron {
    fill: none;

    flex: 0 0 1rem;

    height: 1rem;

    stroke: #6f777e;
    stroke-linecap: round;
    stroke-linejoin: round;
    stroke-width: 2;

    transition: transform 150ms ease;

    width: 1rem;
}

.menu-profil[open] .menu-profil-chevron {
    transform: rotate(180deg);
}


/* ---------------------------------------------------------------------
 * Panneau
 * --------------------------------------------------------------------- */

.menu-profil-panneau {
    background: #ffffff;

    border: 1px solid #e1e5e8;
    border-radius: 0.6rem;

    bottom: calc(100% + 0.4rem);

    box-shadow:
        0 8px 24px rgb(0 0 0 / 10%),
