cd "C:/Users/josselin.didek/Documents/test/Standard" && S="/c/Users/JOSSEL~1.DID/AppData/Local/Temp/claude/c--Users-josselin-didek-Documents-test-Standard/226ff42e-a83b-4e6c-bc41-a6568ceea09c/scratchpad"; cp public/css/garde.css $S/garde-avant-harmonisation.css && cat > /tmp/h.php <<'EOF'
<?php
$f = 'public/css/garde.css';
$lignes = explode("\n", file_get_contents($f));
$debut = 3400; // index 0 de la ligne 3401
$stats = [];
$rgb = fn(string $h) => array_map('hexdec', str_split(strlen($h) === 3 ? preg_replace('/(.)/', '$1$1', $h) : $h, 2));
$lum = function (array $c): float {
    $c = array_map(fn($v) => ($v /= 255) <= 0.03928 ? $v / 12.92 : (($v + 0.055) / 1.055) ** 2.4, $c);
    return .2126 * $c[0] + .7152 * $c[1] + .0722 * $c[2];
};
$teinte = function (array $c): ?string {
    [$r, $g, $b] = $c;
    if (max($c) - min($c) < 40) return null;
    if ($r > $g + 30 && $r > $b + 30 && $g - $b < 25) return 'var(--erreur)';
    if ($r > $b + 40 && $g > $b) return 'var(--avertissement)';
    if ($g > $r + 15 && $g >= $b) return 'var(--confirmation)';
    if ($b > $r + 30) return 'var(--action)';
    return null;
};
$selecteur = '';
for ($i = $debut; $i < count($lignes); $i++) {
    $l = $lignes[$i];
    if (preg_match('/^\S.*\{\s*$/', $l)) { $selecteur = $l; }
    $survol = str_contains($selecteur, ':hover');
    // tailles
    $l = preg_replace_callback('/^(\s+font-size:\s*)([\d.]+)rem(\s*(?:!important)?;)$/', function ($m) use (&$stats) {
        $v = (float) $m[2];
        $t = match (true) {
            $v <= 0.78 => '--texte-xs', $v <= 0.9 => '--texte-s', $v <= 1.0 => '--texte-m',
            $v <= 1.15 => '--texte-l', $v <= 1.4 => '--texte-xl', $v <= 1.8 => '--texte-xxl', default => null,
        };
        if ($t === null) return $m[0];
        $stats['taille']++;
        return $m[1] . "var($t)" . $m[3];
    }, $l);
    // graisses
    $l = preg_replace_callback('/^(\s+font-weight:\s*)(\d+)(\s*(?:!important)?;)$/', function ($m) use (&$stats) {
        $n = match ((int) $m[2]) { 550 => 600, 620, 650, 680 => 700, default => (int) $m[2] };
        if ($n !== (int) $m[2]) $stats['graisse']++;
        return $m[1] . $n . $m[3];
    }, $l);
    // couleurs de texte
    $l = preg_replace_callback('/^(\s+color:\s*)#([0-9a-fA-F]{3}|[0-9a-fA-F]{6})(\s*(?:!important)?;)$/', function ($m) use ($rgb, $lum, $teinte, &$stats) {
        $c = $rgb($m[2]);
        if ($lum($c) > 0.9) return $m[0]; // blanc sur bouton
        $v = $teinte($c) ?? ($lum($c) < 0.05 ? 'var(--texte)' : 'var(--texte-secondaire)');
        $stats['couleur']++;
        return $m[1] . $v . $m[3];
    }, $l);
    // fonds et bordures sombres : boutons principaux
    $l = preg_replace_callback('/^(\s+(?:background|background-color|border-color):\s*)#([0-9a-fA-F]{6})(\s*(?:!important)?;)$/', function ($m) use ($rgb, $lum, $survol, &$stats) {
        $c = $rgb($m[2]);
        if ($lum($c) >= 0.05 || max($c) - min($c) >= 40) return $m[0];
        $stats['bouton']++;
        return $m[1] . ($survol ? 'var(--action-survol)' : 'var(--action)') . $m[3];
    }, $l);
    $lignes[$i] = $l;
}
file_put_contents($f, implode("\n", $lignes));
print_r($stats);
EOF
