.planning-tableau th,
.planning-tableau td {
    background: #ffffff;
    border: 0;
    border-bottom: 1px solid #e7eaec;
    border-right: 1px solid #edf0f2;
    padding: 0.65rem 0.65rem;
    text-align: left;
    vertical-align: top;
}

.planning-tableau tr:last-child th,
.planning-tableau tr:last-child td {
    border-bottom: 0;
}

.planning-tableau th:last-child,
.planning-tableau td:last-child {
    border-right: 0;
}


/* header */

.planning-tableau thead th {
    background: #f8f9fa;
    border-bottom: 1px solid #d8dde0;
    color: var(--texte-secondaire);
    font-size: var(--texte-xs);
    font-weight: 700;
    letter-spacing: 0;
    padding-block: 0.62rem;
    text-align: center;
    text-transform: none;
}

.planning-tableau thead th:first-child {
    min-width: 12rem;
    text-align: left;
    width: 15rem;
}


/* première colonne */

.planning-ligne-intitule {
    background: #fbfcfc !important;
    min-width: 12rem;
    width: 15rem;
}

.planning-ligne-intitule .texte-ligne {
    color: var(--texte);
    display: block;
    font-size: var(--texte-xs);
    font-weight: 700;
    line-height: 1.35;
}


/* hover rangée */

.planning-tableau tbody tr:hover > th,
.planning-tableau tbody tr:hover > td {
    background: #fcfdfd;
}

.planning-tableau tbody tr:hover > .planning-ligne-intitule {
    background: #f7f9fa !important;
}


/* ---------------------------------------------------------------------
 * Modifier ligne
 * --------------------------------------------------------------------- */

.planning-modifier-ligne {
    color: var(--texte-secondaire);
    display: inline-block;
    font-size: var(--texte-xs);
    font-weight: 500;
    margin-top: 0.3rem;
    text-decoration: none;
}

.planning-modifier-ligne:hover {
    color: var(--texte-secondaire);
    text-decoration: underline;
}


/* ---------------------------------------------------------------------
 * Affectation
 * --------------------------------------------------------------------- */

.planning-affectation {
    display: grid;
    gap: 0.08rem;
}

.planning-affectation + .planning-affectation {
    border-top: 1px solid #e9ecee;
    margin-top: 0.55rem;
    padding-top: 0.55rem;
}

.planning-affectation-lien,
.contenu-affectation {
    border-radius: 0.3rem;
    color: inherit;
    display: grid;
    gap: 0.08rem;
    margin: -0.25rem;
    padding: 0.25rem;
    text-decoration: none;
}

.planning-affectation-lien:hover {
    background: #f5f8f9;
    color: inherit;
    outline: 1px solid #dce3e6;
}

.planning-affectation-nom {
    color: var(--texte);
    font-size: var(--texte-xs);
    font-weight: 700;
    line-height: 1.3;
}

.planning-affectation-horaire {
    color: var(--texte-secondaire);
    font-size: var(--texte-xs);
}

.planning-affectation-commentaire {
    color: var(--texte-secondaire);
    font-size: var(--texte-xs);
    font-style: italic;
}

.planning-numero {
    color: var(--texte-secondaire);
    font-size: var(--texte-xs);
    font-variant-numeric: tabular-nums;
    font-weight: 600;
}

.planning-sans-numero {
    color: var(--avertissement);
    font-size: var(--texte-xs);
    font-weight: 600;
}

.planning-case-vide {
    color: var(--texte-secondaire);
    font-size: var(--texte-xs);
    font-style: italic;
}


/* ---------------------------------------------------------------------
 * Ajouter dans une case
 * --------------------------------------------------------------------- */

.tableau-planning-edition td {
    padding-bottom: 2.5rem;
    position: relative;
}

.planning-ajouter-case {
    bottom: 0.45rem;
    color: var(--texte-secondaire);
    font-size: var(--texte-xs);
    font-weight: 600;
    inset-inline: 0.65rem;
    position: absolute;
    text-decoration: none;
}

.planning-ajouter-case:hover {
    color: var(--action);
    text-decoration: none;
}


/* cellule sélectionnée */

.planning-tableau td.case-selectionnee {
    background: #f3f8fa;
    box-shadow: inset 0 0 0 2px rgb(8 122 152 / 25%);
}


/* ---------------------------------------------------------------------
 * Vide
 * --------------------------------------------------------------------- */

.planning-tableau-vide {
    color: var(--texte-secondaire);
    padding: 2rem !important;
    text-align: center !important;
}


/* =====================================================================
 * PANNEAU LATÉRAL
 * ===================================================================== */

.zone-application main:has(.espace-planning.panneau-ouvert) {
    padding-inline-end: calc(25rem + clamp(1.25rem, 2.6vw, 2.6rem));
}

.espace-planning.panneau-ouvert {
    display: block;

