content.content:
 * Commandes du planning
 * --------------------------------------------------------------------- */

.planning-commandes {
    align-items: flex-start;
    display: flex;
    gap: 0.75rem;
    justify-content: space-between;
    margin-bottom: 1rem;
}

.planning-selecteur {
    align-items: end;
    display: flex;
    flex: 1 1 auto;
    gap: 0.55rem;
    max-width: 46rem;
}

.planning-selecteur-champ {
    flex: 1 1 auto;
}

.planning-selecteur label,
.planning-champ label {
    color: var(--texte-secondaire);
    display: block;
    font-size: var(--texte-xs);
    font-weight: 600;
    margin-bottom: 0.3rem;
}

.planning-selecteur select,
.planning-champ select {
    background: #ffffff;
    border: 1px solid #c9d0d4;
    border-radius: 0.35rem;
    color: var(--texte);
    font-size: var(--texte-s);
    height: 2.4rem;
    padding: 0 0.65rem;
}

.planning-afficher {
    background: #ffffff;
    border: 1px solid #cdd3d7;
    border-radius: 0.35rem;
    color: var(--texte);
    font-size: var(--texte-xs);
    font-weight: 600;
    height: 2.4rem;
    padding-inline: 0.8rem;
}

.planning-afficher:hover {
    background: #f5f7f8;
    border-color: #aeb8bd;
    color: var(--texte);
}


/* ---------------------------------------------------------------------
 * Création semaine
 * --------------------------------------------------------------------- */

.planning-creation {
    flex: 0 0 auto;
    position: relative;
}

.planning-creation > summary {
    align-items: center;
    background: #ffffff;
    border: 1px solid #cdd3d7;
    border-radius: 0.35rem;
    color: var(--texte-secondaire);
    cursor: pointer;
    display: flex;
    font-size: var(--texte-xs);
    font-weight: 600;
    gap: 0.55rem;
    list-style: none;
    min-height: 2.4rem;
    padding: 0.45rem 0.7rem;
}

.planning-creation > summary::-webkit-details-marker {
    display: none;
}

.planning-creation > summary::before {
    color: var(--texte-secondaire);
    content: "+";
    font-size: var(--texte-m);
    font-weight: 400;
    line-height: 1;
    width: 0.75rem;
}

.planning-creation[open] > summary::before {
    content: "−";
}

.planning-creation > summary:hover {
    background: #f6f8f9;
    border-color: #adb7bc;
}

.planning-creation-prochaine {
    color: var(--texte-secondaire);
    font-size: var(--texte-xs);
    font-weight: 400;
}

.planning-creation[open] {
    width: min(48rem, 100%);
}

.planning-creation[open] > summary {
    background: #fafbfc;
    border-radius: 0.4rem 0.4rem 0 0;
}

.planning-creation-contenu {
    background: #ffffff;
    border: 1px solid #dfe3e6;
    border-top: 0;
    border-radius: 0 0 0.4rem 0.4rem;
    padding: 1rem;
}

.planning-creation-formulaire {
    align-items: end;
    display: grid;
    gap: 0.8rem;
    grid-template-columns:
        minmax(12rem, 1fr)
        minmax(12rem, 1fr)
        auto;
}

.planning-creation-actions {
    margin: 0;
}

.planning-creation-actions button {
    background: var(--action);
    border: 1px solid #202428;
    border-radius: 0.35rem;
    font-size: var(--texte-xs);
    height: 2.4rem;
    padding-inline: 0.8rem;
}

.planning-creation-actions button:hover {
    background: var(--action-survol);
    border-color: var(--action-survol);
}

.planning-creation-actions button[disabled] {
    background: #eef0f1;
    border-color: #d8dcdf;
    color: var(--texte-secondaire);
}

.planning-creation-vide {
    color: var(--texte-secondaire);
    font-size: var(--texte-s);
    grid-column: 1 / -1;
    margin: 0;
}
        <?= Gabarit::echapper($confirmation) ?>
    </p>
<?php endif; ?>


<div class="planning-commandes">

    <?php if ($plannings !== []): ?>

        <form
            class="planning-selecteur"
            method="get"
            action="/planning"
        >
            <div class="planning-selecteur-champ">
                <label for="planning-id">
                    Semaine affichée
