                >
                    <?php foreach ($plannings as $semaine): ?>

                        <option
                            value="<?= Gabarit::echapper($semaine['id']) ?>"
                            <?= $planningId === (int) $semaine['id']
                                ? 'selected'
                                : '' ?>
                        >
                            <?= Gabarit::echapper($semaine['libelle']) ?>
                            —
                            <?= Gabarit::echapper(
