                                    (string) $semaine['date_fin'],
                                )
                            ) ?>
                            —
                            <?= $semaine['statut'] === 'publie'
                                ? 'publiée'
                                : 'brouillon' ?>
                        </option>

                    <?php endforeach; ?>
                </select>
            </div>

            <button
                class="planning-afficher"
                type="submit"
