    background: #ffffff;
    border: 1px solid #cdd3d7;
    border-radius: 0.35rem;
    color: var(--texte-secondaire);
    cursor: pointer;
    display: flex;
    font-size: var(--texte-xs);
    font-weight: 600;
    gap: 0.55rem;
    list-style: none;
    min-height: 2.4rem;
    padding: 0.45rem 0.7rem;
}

.planning-creation > summary::-webkit-details-marker {
    display: none;
}

.planning-creation > summary::before {
    color: var(--texte-secondaire);
    content: "+";
    font-size: var(--texte-m);
    font-weight: 400;
    line-height: 1;
    width: 0.75rem;
}

.planning-creation[open] > summary::before {
    content: "−";
}

.planning-creation > summary:hover {
    background: #f6f8f9;
    border-color: #adb7bc;
