// rechargent la page avec des paramètres d'adresse, et le serveur rend le
// panneau ouvert sur le bon mode. Le module supprime ce rechargement et rend
// le panneau utilisable au clavier — il ne conditionne aucune fonctionnalité
// (CDC § 10, amélioration progressive ; recette, critère 12).

const espace = document.getElementById('espace-planning');
