    private static function nettoyer(string $identifiant): string
    {
        $valeur = trim($identifiant);

        $position = strrpos($valeur, '\\');
        if ($position !== false) {
            $valeur = substr($valeur, $position + 1);
        }

        $arobase = strpos($valeur, '@');
        if ($arobase !== false) {
            $valeur = substr($valeur, 0, $arobase);
        }

        return mb_strtolower(trim($valeur), 'UTF-8');
    }
