                  ORDER BY role'
            );
            $lecture->execute([$utilisateurId]);
            $avant = array_map(
                static fn(mixed $valeur): string => (string) $valeur,
                $lecture->fetchAll(PDO::FETCH_COLUMN),
            );

            if ($avant === $apres) {
                $base->commit();
                return;
