            $insertion = $base->prepare(
                'INSERT INTO utilisateur_role (utilisateur_id, role) VALUES (?, ?)'
            );
            foreach ($apres as $role) {
                $insertion->execute([$utilisateurId, $role]);
            }

            Journal::consigner(
                $base,
                $utilisateurId,
                $login,
                'synchronisation_roles_annuaire',
