                json_encode($avant, JSON_UNESCAPED_UNICODE | JSON_THROW_ON_ERROR),
                json_encode($apres, JSON_UNESCAPED_UNICODE | JSON_THROW_ON_ERROR),
            );
            $base->commit();
        } catch (Throwable $erreur) {
            if ($base->inTransaction()) {
                $base->rollBack();
            }
            throw $erreur;
