titre('Traçabilité et échappement');

accepte(
    'les rôles de l’annuaire remplacent les rôles locaux et sont journalisés',
    static function () use ($base, $cibleAnnuaire): void {
        $synchronise = Utilisateur::parLogin(
            $base,
            $cibleAnnuaire->login,
            [Role::Consultation, Role::Administrateur],
        );

        verifier($synchronise->a(Role::Consultation), 'le rôle consultation est absent');
        verifier($synchronise->a(Role::Administrateur), 'le rôle administrateur est absent');
        verifier(!$synchronise->a(Role::Standard), 'l’ancien rôle standard est encore présent');

        $requete = $base->prepare(
            'SELECT valeur_avant, valeur_apres
               FROM journal_audit
              WHERE action = ? AND cible_id = ?
           ORDER BY id DESC
              LIMIT 1'
        );
        $requete->execute([
            'synchronisation_roles_annuaire',
            $cibleAnnuaire->id,
        ]);
        $ligne = $requete->fetch();

        verifier($ligne !== false, 'la synchronisation n’est pas journalisée');
        verifier($ligne['valeur_avant'] === '["standard"]', 'valeur avant incorrecte');
        verifier(
            $ligne['valeur_apres'] === '["administrateur","consultation"]',
            'valeur après incorrecte',
        );
    },
);

