// Comptes et rôles : « Enregistrer » reste grisé tant que les cases cochées
// sont celles de la base. Sans JavaScript le bouton reste actif, et un envoi
// sans changement est sans effet côté serveur (rien n'est journalisé).

for (const formulaire of document.querySelectorAll('form[data-suivi-modifications]')) {
  const bouton = formulaire.querySelector('button[type="submit"]');
  const cases = [...formulaire.querySelectorAll('input[type="checkbox"]')];
  if (!(bouton instanceof HTMLButtonElement) || cases.length === 0) {
    continue;
  }

  // defaultChecked reflète l'attribut « checked » rendu par le serveur :
  // décocher puis recocher une case revient à l'état initial.
  const actualiser = () => {
    bouton.disabled = cases.every((c) => c.checked === c.defaultChecked);
  };

  formulaire.addEventListener('change', actualiser);
  // Retour arrière du navigateur : les cases peuvent être restaurées modifiées.
  window.addEventListener('pageshow', actualiser);
  actualiser();
}
EOF
