const normaliser = (valeur) => valeur
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLocaleUpperCase('fr')
  .replace(/\s+/g, ' ')
  .trim();

for (const formulaire of document.querySelectorAll('[data-recherche-locale]')) {
  const champ = formulaire.querySelector('[data-champ-recherche]');
  const resultat = formulaire.querySelector('[data-resultats-recherche]');
  const elements = [...document.querySelectorAll('[data-element-recherche]')];

  if (!(champ instanceof HTMLInputElement) || elements.length === 0) {
    continue;
  }

  const filtrer = () => {
    const termes = normaliser(champ.value).split(' ').filter(Boolean);
    let visibles = 0;

    for (const element of elements) {
      const contenu = normaliser(element.dataset.recherche ?? element.textContent ?? '');
      const visible = termes.every((terme) => contenu.includes(terme));
      element.hidden = !visible;
      if (visible) {
        visibles++;
      }
    }

    if (resultat instanceof HTMLOutputElement) {
      resultat.textContent = `${visibles} personne${visibles > 1 ? 's' : ''}`;
    }
  };

  champ.addEventListener('input', filtrer);
  filtrer();
}
