 * ===================================================================== */

/* ---------------------------------------------------------------------
 * Header
 * --------------------------------------------------------------------- */

.comptes-header {
    align-items: flex-end;
    display: flex;
    justify-content: space-between;
    margin-bottom: 1.75rem;
}

.comptes-header h1 {
    color: var(--texte);
    font-size: var(--texte-xxl);
    font-weight: 700;
    letter-spacing: -0.035em;
    line-height: 1.15;
    margin: 0;
}

.comptes-header p {
    color: var(--texte-secondaire);
    font-size: var(--texte-s);
    margin: 0.45rem 0 0;
}


/* ---------------------------------------------------------------------
 * Confirmation
 * --------------------------------------------------------------------- */

.comptes-confirmation {
    background: #f0fdf4;
    border: 1px solid #bbf7d0;
    border-radius: 0.65rem;
    color: var(--confirmation);
    font-size: var(--texte-s);
    font-weight: 600;
    margin-bottom: 1rem;
    padding: 0.7rem 0.9rem;
}


/* ---------------------------------------------------------------------
 * Panel
 * --------------------------------------------------------------------- */

.comptes-description {
    color: var(--texte-secondaire);
    font-size: var(--texte-s);
    margin: 0 0 1.25rem;
}

.comptes-panel {
    background: #ffffff;
    border: 1px solid #e1e5e8;
    border-radius: 0.5rem;
    box-shadow:
        0 1px 2px rgb(0 0 0 / 2%),
        0 3px 8px rgb(0 0 0 / 2%);
    overflow: hidden;
}

.comptes-panel-header {
    align-items: center;
    border-bottom: 1px solid #eceef0;
    display: flex;
    justify-content: space-between;
    padding: 0.9rem 1.1rem;
}

.comptes-panel-header h2 {
    color: var(--texte);
    font-size: var(--texte-m);
    font-weight: 700;
    margin: 0;
}

.comptes-panel-header p {
    color: var(--texte-secondaire);
    font-size: var(--texte-xs);
    margin: 0.2rem 0 0;
}


/* ---------------------------------------------------------------------
 * Table
 * --------------------------------------------------------------------- */

.comptes-table-wrapper {
    overflow-x: auto;
}

.comptes-table {
    border-collapse: collapse;
    table-layout: auto;
    width: 100%;
}

.comptes-table th,
.comptes-table td {
    border: 0;
    border-bottom: 1px solid #edf0f2;
    padding: 0.9rem 1.25rem;
    text-align: left;
    vertical-align: middle;
}

.comptes-table tbody tr:last-child th,
.comptes-table tbody tr:last-child td {
    border-bottom: 0;
}


/* ---------------------------------------------------------------------
 * Colonnes
 * --------------------------------------------------------------------- */

.comptes-table thead th {
    background: #fafbfc;
    color: var(--texte-secondaire);
    font-size: var(--texte-xs);
    font-weight: 600;
    letter-spacing: 0.015em;
    padding-block: 0.65rem;
    text-transform: none;
}

.comptes-table thead th:nth-child(1) {
    width: 25%;
}

.comptes-table thead th:nth-child(2) {
    width: 10%;
}

.comptes-table thead th:nth-child(3) {
    width: 16%;
}

.comptes-table thead th:nth-child(4) {
    width: 49%;
}


/* ---------------------------------------------------------------------
 * Row interaction
 * --------------------------------------------------------------------- */

.comptes-table tbody tr {
    transition: background-color 100ms ease;
}

.comptes-table tbody tr:hover {
    background: #fbfcfd;
}


/* ---------------------------------------------------------------------
 * Identité
 * --------------------------------------------------------------------- */

.compte-identite {
    display: grid;
    gap: 0.12rem;
}

.compte-nom {
    color: var(--texte);
    display: block;
    font-size: var(--texte-s);
    font-weight: 700;
    line-height: 1.25;
}

.compte-login {
    color: var(--texte-secondaire);
    display: block;
    font-size: var(--texte-xs);
    font-weight: 400;
    line-height: 1.3;
}

/* ---------------------------------------------------------------------
 * Statuts
 * --------------------------------------------------------------------- */

.compte-statut {
    align-items: center;
    display: inline-flex;
    font-size: var(--texte-xs);
    font-weight: 600;
    gap: 0.4rem;
}

.compte-statut > span {
    border-radius: 50%;
    height: 0.425rem;
    width: 0.425rem;
}

.compte-statut--actif {
    color: var(--confirmation);
}

.compte-statut--actif > span {
    background: #3f8c63;
    box-shadow: 0 0 0 3px #e9f5ee;
}

.compte-statut--inactif {
    color: var(--texte-secondaire);
}

.compte-statut--inactif > span {
    background: #9da3aa;
}


/* ---------------------------------------------------------------------
 * Connexion
 * --------------------------------------------------------------------- */

.compte-connexion {
    color: var(--texte-secondaire);
    font-size: var(--texte-s);
    font-variant-numeric: tabular-nums;
}

.compte-jamais {
    color: var(--texte-secondaire);
}


/* ---------------------------------------------------------------------
 * Tags
 * --------------------------------------------------------------------- */

.roles-tags {
    display: flex;
    flex-wrap: wrap;
    gap: 0.35rem;
}

.role-tag {
    background: #f5f7f8;
    border: 1px solid #e1e5e8;
    border-radius: 0.3rem;
    color: var(--texte-secondaire);
    font-size: var(--texte-xs);
    font-weight: 600;
    line-height: 1;
    padding: 0.32rem 0.45rem;
}

.role-vide {
    color: var(--texte-secondaire);
    font-size: var(--texte-s);
}


/* ---------------------------------------------------------------------
 * Edition
 * --------------------------------------------------------------------- */

.roles-form {
    align-items: center;
    display: flex;
    gap: 1rem;
    justify-content: space-between;
    margin: 0;
}

.roles-form fieldset {
    flex: 1 1 auto;
    margin: 0;
}

.roles-options {
    display: flex;
    flex-wrap: wrap;
    gap: 0.4rem;
}


/* ---------------------------------------------------------------------
 * Roles selection
 * --------------------------------------------------------------------- */

.role-option {
    align-items: center;
    background: #ffffff;
    border: 1px solid #dfe3e6;
    border-radius: 0.35rem;
    color: var(--texte-secondaire);
    cursor: pointer;
    display: inline-flex;
    font-size: var(--texte-xs);
    font-weight: 500;
    gap: 0.4rem;
    min-height: 2rem;
    padding: 0.35rem 0.55rem;
    transition:
        background 100ms ease,
        border-color 100ms ease,
        color 100ms ease,
        box-shadow 100ms ease;
}

.role-option:hover {
    background: #f8fafb;
    border-color: #bec9ce;
}

.role-option input {
    accent-color: #006782;
    height: 0.9rem;
    margin: 0;
    width: 0.9rem;
}

.role-option:has(input:checked) {
    background: #f1f8fa;
    border-color: #9ac7d1;
    color: var(--action);
    box-shadow: inset 0 0 0 1px rgb(0 103 130 / 5%);
}


/* ---------------------------------------------------------------------
 * Button
 * --------------------------------------------------------------------- */

.roles-save {
    background: var(--action);
    border: 1px solid #202428;
    border-radius: 0.35rem;
    color: #ffffff;
    flex: 0 0 auto;
    font-size: var(--texte-xs);
    font-weight: 600;
    min-height: 2rem;
    padding: 0.35rem 0.7rem;
    transition:
        background-color 100ms ease,
        border-color 100ms ease,
        transform 80ms ease;
}

.roles-save:hover {
    background: var(--action-survol);
    border-color: var(--action-survol);
}

.roles-save:active {
    transform: translateY(1px);
}

/* Aucun changement à enregistrer (comptes.mjs). Plus spécifique que la
 * règle générale button[disabled], que .roles-save écraserait. */
.roles-save[disabled],
.roles-save[disabled]:hover {
    background: var(--fond-secondaire);
    border-color: var(--bordure-fine);
    color: var(--texte-secondaire);
    cursor: not-allowed;
    transform: none;
}


/* ---------------------------------------------------------------------
 * Responsive
 * --------------------------------------------------------------------- */

@media (max-width: 75rem) {

    .roles-form {
        align-items: flex-start;
        flex-direction: column;
    }
}


@media (max-width: 58rem) {

    .comptes-panel {
        border-radius: 0.65rem;
    }

    .comptes-table {
        min-width: 55rem;
    }
}

