// Page de connexion : confort de saisie seulement. Le formulaire est traité
// par Apache (mod_auth_form) et fonctionne entièrement sans ce module.

const formulaire = document.querySelector('form[data-connexion]');
const motDePasse = document.getElementById('mot-de-passe');
const afficher = document.querySelector('[data-afficher-mot-de-passe]');
const majuscules = document.querySelector('[data-alerte-majuscules]');

if (motDePasse instanceof HTMLInputElement && afficher instanceof HTMLButtonElement) {
  afficher.hidden = false;
  afficher.addEventListener('click', () => {
    const visible = motDePasse.type === 'password';
    motDePasse.type = visible ? 'text' : 'password';
    afficher.textContent = visible ? 'Masquer' : 'Afficher';
    afficher.setAttribute('aria-pressed', String(visible));
    motDePasse.focus();
  });
}

// Première cause d'échec au clavier : le verrouillage des majuscules, qu'on
// ne voit pas dans un champ masqué.
if (motDePasse instanceof HTMLInputElement && majuscules instanceof HTMLElement) {
  const verifier = (evenement) => {
    if (evenement instanceof KeyboardEvent) {
      majuscules.hidden = !evenement.getModifierState('CapsLock');
    }
  };
  motDePasse.addEventListener('keydown', verifier);
  motDePasse.addEventListener('keyup', verifier);
  motDePasse.addEventListener('blur', () => { majuscules.hidden = true; });
}

// Un double clic enverrait deux fois les identifiants ; le libellé confirme
// que la demande est partie, l'annuaire pouvant mettre une seconde à répondre.
if (formulaire instanceof HTMLFormElement) {
  const bouton = formulaire.querySelector('button[type="submit"]');
  formulaire.addEventListener('submit', () => {
    if (motDePasse instanceof HTMLInputElement) {
      motDePasse.type = 'password';
    }
    if (bouton instanceof HTMLButtonElement) {
      bouton.disabled = true;
      bouton.textContent = 'Connexion…';
    }
  });

  // Retour arrière depuis la page suivante : la page revient du cache avec
  // le bouton encore désactivé.
  window.addEventListener('pageshow', () => {
    if (bouton instanceof HTMLButtonElement) {
      bouton.disabled = false;
      bouton.textContent = 'Se connecter';
    }
  });
}

