input.content:
/* =====================================================================
 * Connexion
 *
 * Même vocabulaire que l'application (fond, cartes, accent --action) :
 * l'agent qui se connecte doit reconnaître l'outil qu'il va utiliser.
 * ===================================================================== */

.connexion-page {
    background: #f6f7f8;
    color: var(--texte);
    min-height: 100vh;
}


/* ---------------------------------------------------------------------
 * Layout
 * --------------------------------------------------------------------- */

.connexion-contenu {
    align-items: center;
    display: flex;
    justify-content: center;
    min-height: 100vh;
    padding: 2rem 1.25rem;
}


/* ---------------------------------------------------------------------
 * Bloc — mêmes rayon et ombre que les cartes de la barre latérale
 * --------------------------------------------------------------------- */

.connexion-bloc {
    background: #ffffff;
    border: 1px solid #e4e7e9;
    border-radius: 0.85rem;
    box-shadow:
        0 1px 2px rgb(0 0 0 / 3%),
        0 6px 18px rgb(0 0 0 / 4%);
    margin: 0;
    max-width: 24rem;
    padding: 2rem 2rem 1.5rem;
    width: 100%;
}


/* ---------------------------------------------------------------------
 * Marque
 * --------------------------------------------------------------------- */

.connexion-marque {
    margin-bottom: 1.75rem;
}

.connexion-logo {
    display: block;
    height: auto;
    margin: 0;
    /* Le logo est un JPEG sur fond blanc : la carte blanche l'absorbe. */
    max-width: 9.5rem;
    width: 100%;
}

.connexion-marque p {
    color: var(--texte-secondaire);
    font-size: var(--texte-xs);
    font-weight: 600;
    margin: 0.6rem 0 0;
}


/* ---------------------------------------------------------------------
 * Titre
 * --------------------------------------------------------------------- */

.connexion-titre {
    color: var(--texte);
    font-size: 1.35rem;
    font-weight: 700;
    letter-spacing: -0.02em;
    line-height: 1.2;
    margin: 0 0 1.25rem;
}


/* ---------------------------------------------------------------------
 * Formulaire
 * --------------------------------------------------------------------- */

.connexion-formulaire {
    margin: 0;
}

.connexion-champ + .connexion-champ {
    margin-top: 1.1rem;
}

.connexion-champ label {
    color: var(--texte);
    display: block;
    font-size: var(--texte-s);
    font-weight: 600;
    margin-bottom: 0.35rem;
}

/* WCAG 1.4.11 : la limite du champ est ce qui le fait voir, 3:1 au moins
 * (--bordure). */
.connexion-champ input {
    background: #ffffff;
    border: 1px solid var(--bordure);
    border-radius: 0.45rem;
    color: var(--texte);
    font-size: var(--texte-m);
    height: 2.75rem;
    padding: 0 0.75rem;
    transition: border-color 100ms ease;
    width: 100%;
}

.connexion-champ input:hover {
    border-color: #5f676c;
}

/* Contour plein et contrasté : le halo translucide d'avant ne se voyait
 * pas sur un écran de poste de soins (WCAG 2.4.7). */
.connexion-champ input:focus-visible,
.connexion-champ input:focus {
    border-color: var(--action);
    outline: 2px solid var(--action);
    outline-offset: 0;
}

.connexion-indice {
    color: var(--texte-secondaire);
    font-size: var(--texte-xs);
    line-height: 1.4;
    margin: 0.35rem 0 0;
}


/* ---------------------------------------------------------------------
 * Mot de passe : bouton Afficher dans le champ
 * --------------------------------------------------------------------- */

.connexion-saisie-secrete {
    position: relative;
}

.connexion-saisie-secrete input {
    padding-right: 5.5rem;
}

.connexion-afficher {
    background: none;
    border: 0;
    border-radius: 0.35rem;
    color: var(--action);
    cursor: pointer;
    font-size: var(--texte-xs);
    font-weight: 600;
    min-height: 2rem;
    padding: 0 0.6rem;
    position: absolute;
    right: 0.4rem;
    top: 50%;
    transform: translateY(-50%);
}

.connexion-afficher:hover {
    background: #f3f8fa;
    color: var(--action-survol);
}

.connexion-majuscules {
    color: var(--avertissement);
    font-size: var(--texte-xs);
    font-weight: 600;
    margin: 0.35rem 0 0;
}


/* ---------------------------------------------------------------------
 * Bouton — l'accent de l'application, pas un noir étranger à l'outil
 * --------------------------------------------------------------------- */

.connexion-bouton {
    background: var(--action);
    border: 1px solid var(--action);
    border-radius: 0.45rem;
    color: #ffffff;
    cursor: pointer;
    font-size: var(--texte-m);
    font-weight: 600;
    margin-top: 1.5rem;
    min-height: 2.75rem;
    padding: 0.5rem 0.9rem;
    transition: background-color 100ms ease, border-color 100ms ease;
    width: 100%;
}

.connexion-bouton:hover {
    background: var(--action-survol);
    border-color: var(--action-survol);
}

.connexion-bouton:focus-visible {
    outline: 2px solid var(--focus);
    outline-offset: 2px;
}

/* Envoi en cours (connexion.mjs) : reste lisible, la règle générale
 * button[disabled] le rendrait gris comme un bouton indisponible. */
.connexion-bouton[disabled] {
    background: var(--action-survol);
    border-color: var(--action-survol);
    color: #ffffff;
    cursor: progress;
}


/* ---------------------------------------------------------------------
 * Erreur
 * --------------------------------------------------------------------- */

/* Masqué par défaut : Apache ne renvoie vers « #erreur » qu'après un échec
 * d'authentification (vhost.conf, AuthFormLoginRequiredLocation). Sans cette
 * règle, le message s'afficherait dès la première visite. */
.connexion-erreur {
    display: none;
}

.connexion-erreur:target {
    background: #fdf3f3;
    border: 1px solid #efcaca;
    border-radius: 0.45rem;
    color: var(--erreur);
    display: block;
    font-size: var(--texte-s);
    line-height: 1.5;
    margin: 0 0 1.25rem;
    padding: 0.7rem 0.85rem;
}

.connexion-erreur strong {
    font-weight: 700;
}


/* ---------------------------------------------------------------------
 * Aide
 * --------------------------------------------------------------------- */

/* --texte-secondaire et non plus #969ca2, qui n'atteignait que 2,8:1. */
.connexion-aide {
    border-top: 1px solid #eceff1;
    color: var(--texte-secondaire);
    font-size: var(--texte-xs);
    line-height: 1.45;
    margin: 1.75rem 0 0;
    padding-top: 1rem;
    text-align: center;
}


/* ---------------------------------------------------------------------
 * Responsive
 * --------------------------------------------------------------------- */

@media (max-width: 32rem) {

    .connexion-contenu {
        align-items: flex-start;
        padding: 1rem;
    }

    .connexion-bloc {
        box-shadow: none;
        margin-top: 1.5rem;
        padding: 1.5rem 1.25rem 1.25rem;
    }
}

