/* ---------------------------------------------------------------------
 * Titre
 * --------------------------------------------------------------------- */

.connexion-entete {
    margin-bottom: 1.35rem;
}

.connexion-entete h1 {
    color: #191c20;
    font-size: 1.45rem;
    font-weight: 680;
    letter-spacing: -0.03em;
    line-height: 1.2;
    margin: 0;
}

.connexion-entete p {
    color: #747c83;
    font-size: 0.8rem;
    line-height: 1.5;
    margin: 0.35rem 0 0;
}


/* ---------------------------------------------------------------------
 * Formulaire
 * --------------------------------------------------------------------- */

.connexion-formulaire {
    margin: 0;
}

.connexion-champ + .connexion-champ {
    margin-top: 1rem;
}

.connexion-champ label {
    color: #4c545a;
    display: block;
    font-size: 0.74rem;
    font-weight: 600;
    margin-bottom: 0.35rem;
}

.connexion-champ input {
    background: #ffffff;
    border: 1px solid #bfc8cd;
    border-radius: 0.35rem;
    color: #202428;
    font-size: 0.85rem;
    height: 2.65rem;
    padding: 0 0.7rem;
    transition:
        border-color 100ms ease,
        box-shadow 100ms ease;
    width: 100%;
}

.connexion-champ input::placeholder {
    color: #a0a6ac;
}

.connexion-champ input:hover {
    border-color: #9ea9ae;
}

.connexion-champ input:focus {
    border-color: #62818d;
    box-shadow: 0 0 0 3px rgb(8 122 152 / 10%);
    outline: 0;
}


/* ---------------------------------------------------------------------
 * Bouton
 * --------------------------------------------------------------------- */

.connexion-bouton {
    background: #202428;
    border: 1px solid #202428;
    border-radius: 0.35rem;
    color: #ffffff;
    font-size: 0.8rem;
    font-weight: 620;
    margin-top: 1.25rem;
    min-height: 2.65rem;
    padding: 0.5rem 0.9rem;
    transition:
        background-color 100ms ease,
        border-color 100ms ease,
        transform 80ms ease;
    width: 100%;
}

.connexion-bouton:hover {
    background: #101214;
    border-color: #101214;
}

.connexion-bouton:active {
    transform: translateY(1px);
}


/* ---------------------------------------------------------------------
 * Erreur
 * --------------------------------------------------------------------- */

/* Masqué par défaut : Apache ne renvoie vers « #erreur » qu'après un échec
 * d'authentification (vhost.conf, AuthFormLoginRequiredLocation). Sans cette
 * règle, le message s'afficherait dès la première visite. */
.connexion-erreur {
    display: none;
}

.connexion-erreur:target {
    background: #fdf3f3;
    border: 1px solid #efcaca;
    border-radius: 0.35rem;
    color: var(--erreur);
    display: block;
    font-size: 0.8rem;
    line-height: 1.5;
    margin: 0 0 1rem;
    padding: 0.7rem 0.8rem;
}

.connexion-erreur strong {
    font-weight: 700;
}


/* ---------------------------------------------------------------------
 * Aide
 * --------------------------------------------------------------------- */

.connexion-aide {
    border-top: 1px solid #eceff1;
    color: #969ca2;
    font-size: 0.68rem;
    line-height: 1.45;
    margin: 1.5rem 0 0;
    padding-top: 1rem;
}


/* ---------------------------------------------------------------------
 * Responsive
 * --------------------------------------------------------------------- */

@media (max-width: 32rem) {

    .connexion-contenu {
        align-items: flex-start;
        padding: 1rem;
    }

    .connexion-bloc {
        border-radius: 0.4rem;
        box-shadow: none;
        margin-top: 2rem;
        padding: 1.35rem;
    }

    .connexion-logo {
        max-width: 9rem;
    }
}

