 * côte à côte, ils s'alignent au pixel. Trois niveaux seulement — action
 * principale, action secondaire, action destructrice — distingués par le
 * remplissage et non par la seule teinte.
 * ===================================================================== */

.bouton,
.bouton-action,
button {
    background: var(--action);
    border: var(--controle-bordure) solid var(--action);
    border-radius: var(--rayon-controle);
    color: #ffffff;
    cursor: pointer;
    display: inline-block;
    font: inherit;
    font-weight: 700;
    line-height: 1.45;
    padding: var(--controle-vertical) var(--controle-horizontal);
    text-align: center;
    text-decoration: none;
    transition: background-color 140ms ease, border-color 140ms ease,
                color 140ms ease, transform 120ms cubic-bezier(0.23, 1, 0.32, 1);
    white-space: nowrap;
}

.bouton:active,
.bouton-action:active,
button:active {
    transform: scale(0.98);
}

.bouton:hover,
.bouton-action:hover,
button:hover {
    background: var(--action-survol);
    border-color: var(--action-survol);
    color: #ffffff;
}

.bouton-secondaire,
.suppression-telephone button {
    background: var(--fond);
    color: var(--action);
}

.bouton-secondaire:hover {
    background: var(--action);
    color: var(--fond);
}

button.bouton-danger,
button.bouton-danger:hover {
    background: var(--erreur);
    border-color: var(--erreur);
    color: #ffffff;
}

.suppression-telephone button {
    border-color: var(--erreur);
    color: var(--erreur);
}

.suppression-telephone button:hover {
    background: var(--erreur);
    border-color: var(--erreur);
    color: #ffffff;
}

button[disabled] {
    background: var(--fond-secondaire);
    border-color: var(--bordure);
    color: var(--texte-secondaire);
    cursor: not-allowed;
}

/* Action discrète, au fil du texte ou dans une cellule : ce n'est pas un

input:not([type="checkbox"]):not([type="radio"]):focus,
select:focus,
textarea:focus {
    border-color: var(--focus);
    outline: 3px solid var(--focus);
    outline-offset: 1px;
}

.bouton,
.bouton-action,
button {
    align-items: center;
    background: var(--action);
    border: 1px solid var(--action);
    border-radius: var(--rayon-controle);
    color: #ffffff;
    display: inline-flex;
    font-size: var(--texte-s);
    font-weight: 700;
    justify-content: center;
    min-height: 2.75rem;
    padding: 0.55rem 0.9rem;
    text-decoration: none;
}

.bouton:hover,
.bouton-action:hover,
button:hover {
    background: var(--action-survol);
    border-color: var(--action-survol);
    color: #ffffff;
}

.bouton-secondaire,
.bouton-action.bouton-secondaire {
    background: var(--fond-elevation);
    border-color: var(--bordure-fine);
    color: var(--texte);
}

.bouton-secondaire:hover,
.bouton-action.bouton-secondaire:hover {
    background: var(--fond-secondaire);
    border-color: var(--bordure);
    color: var(--texte);
}

button.bouton-danger,
.bouton-danger {
    background: var(--fond-elevation);
    border-color: var(--erreur);
    color: var(--erreur);
}

button.bouton-danger:hover,
.bouton-danger:hover {
    background: #fff0f0;
    border-color: var(--erreur);
    color: var(--erreur);
}

.lien-discret {
    color: var(--action);
    font-size: var(--texte-s);
    font-weight: 600;
    .choix-semaine label,
    .recherche-maintenant label {
        grid-column: auto;
    }

    /* Un bouton qui soumet un formulaire pleine largeur s'étend ; un bouton
     * d'une barre d'actions garde sa taille, sinon trois actions voisines
     * deviennent trois bandeaux empilés. */
    .recherche button,
    .recherche-maintenant button,
    .formulaire-telephone button,
    .choix-semaine button,
    .formulaire-horizontal button,
    .panneau-actions button,
    .actions-formulaire button {
        width: 100%;
    }

    .zone-danger input:not([type="checkbox"]) {
        width: 100%;
    }

