content.content:
    margin: 0;
}

.apercu-bouton-principal,
.apercu-bouton-secondaire,
.apercu-bouton-depublier {
    align-items: center;
    border-radius: 0.35rem;
    display: inline-flex;
    font-size: var(--texte-xs);
    font-weight: 600;
    justify-content: center;
    min-height: 2.2rem;
    padding: 0.4rem 0.75rem;
    text-decoration: none;
    white-space: nowrap;
}


/* Publier */

.apercu-bouton-principal {
    background: var(--action);
    border: 1px solid #202428;
    color: #ffffff;
}

.apercu-bouton-principal:hover {
    background: var(--action-survol);
    border-color: var(--action-survol);
}


/* Modifier */

.apercu-bouton-secondaire {
    flex-wrap: wrap;
    gap: 0.4rem;
    justify-content: flex-end;
}

.planning-action {
    align-items: center;
    border-radius: 0.35rem;
    display: inline-flex;
    font-size: var(--texte-xs);
    font-weight: 600;
    justify-content: center;
    min-height: 2.15rem;
    padding: 0.4rem 0.65rem;
    text-decoration: none;
    white-space: nowrap;
}

.planning-action--principale {
    background: var(--action);
    border: 1px solid #202428;
    color: #ffffff;
}

.planning-action--principale:hover {
    background: var(--action-survol);
    border-color: var(--action-survol);
    color: #ffffff;
}

.planning-action--secondaire {
     * larges faisaient déborder le pied et apparaître des défilements. */
    margin: auto -1rem -1rem;
    padding: 0.8rem 1rem;
}

#panneau-affectation-modifier .panneau-actions button {
    width: 100%;
}

.groupe-horaires {
    border: 0;
    margin: var(--pas) 0;
    min-width: 0;
    padding: 0;
}
}

.panneau-actions button {
    background: var(--action);
    border: 1px solid #202428;
    border-radius: 0.35rem;
    font-size: var(--texte-xs);
    font-weight: 600;
    min-height: 2.25rem;
}

.panneau-actions button:hover {
    background: var(--action-survol);
    border-color: var(--action-survol);
}

.panneau-actions .lien-discret {
    color: var(--texte-secondaire);
    font-size: var(--texte-xs);
    margin: 0;
    text-decoration: none;
