    public function traiter(string $methode, string $chemin, Utilisateur $utilisateur): array
    {
        $methode = strtoupper($methode);
        $cheminConnu = false;

        foreach ($this->routes as $route) {
     * Les routes accessibles à un compte, pour construire la navigation.
     *
     * La navigation est construite à partir de la même table que le contrôle :
     * un menu ne peut pas proposer une page interdite, ni omettre une page
     * permise.
     *
     * @return list<string>
     */
    public function cheminsAccessibles(Utilisateur $utilisateur): array
    {
        $chemins = [];

        foreach ($this->routes as $route) {
            if ($route['methode'] !== 'GET'
                || !$route['navigation']
