// du côté fermé (voir Routeur).
// ---------------------------------------------------------------------

(new ControleurGarde($base, $routeur))->enregistrerRoutes();
(new ControleurPlanning($base, $routeur))->enregistrerRoutes();
(new ControleurPersonnes($base, $routeur))->enregistrerRoutes();
(new ControleurComptes($base, $routeur))->enregistrerRoutes();

// ---------------------------------------------------------------------
// Traitement de la requête
// ---------------------------------------------------------------------

$chemin = parse_url((string) ($_SERVER['REQUEST_URI'] ?? '/'), PHP_URL_PATH);
$methode = (string) ($_SERVER['REQUEST_METHOD'] ?? 'GET');

$pageErreur = static function (
    int $code,
    string $titre,
    string $message,
) use ($routeur, $utilisateur, $chemin): array {
    return [
        'statut' => $code,
        'contenu' => Gabarit::rendre('erreurs/erreur', [
            'titre' => $titre,
            'code' => $code,
            'message' => $message,
            'utilisateur' => $utilisateur,
            'routeur' => $routeur,
            'cheminCourant' => is_string($chemin) ? $chemin : '/',
        ]),
    ];
};

try {
    $resultat = is_string($chemin) && $chemin !== ''
        ? $routeur->traiter($methode, $chemin, $utilisateur)
        : $pageErreur(
            400,
            'Adresse invalide',
            'L’adresse demandée n’est pas valide. Revenez à l’accueil et '
            . 'utilisez la navigation de l’application.',
        );
} catch (Throwable $exception) {
    // Le message d'origine peut contenir un chemin de fichier ou un fragment
    // de requête : il part au journal du serveur, jamais à la page.
    error_log($exception->getMessage());
    $resultat = $pageErreur(
        500,
        'Erreur interne',
        'L’opération n’a pas pu aboutir. Aucun détail technique n’est affiché ; '
        . 'réessayez puis contactez la DSN si le problème persiste.',
