    margin: 0;
    max-width: 60rem;
}

.lignes-alerte {
    background: #fdf7ee;
    border: 1px solid #ecd6b5;
    border-radius: 0.65rem;
    color: var(--avertissement);
    font-size: var(--texte-s);
    margin: 0 0 1rem;
    padding: 0.7rem 0.9rem;
}

.lignes-panneau {
    background: #ffffff;
    border: 1px solid #e1e5e8;
    border-radius: 0.5rem;
    box-shadow: 0 1px 2px rgb(0 0 0 / 2%), 0 3px 8px rgb(0 0 0 / 2%);
    overflow-x: auto;
}

.lignes-tableau {
    border-collapse: collapse;
    font-size: var(--texte-s);
    width: 100%;
}

.lignes-tableau th,
.lignes-tableau td {
    border: 0;
    border-bottom: 1px solid #edf0f2;
    padding: 0.75rem 1rem;
    text-align: left;
    vertical-align: top;
}

.lignes-tableau thead th {
    background: #fafbfc;
    color: var(--texte-secondaire);
    font-size: var(--texte-xs);
    font-weight: 600;
    padding-block: 0.65rem;
    text-transform: none;
    white-space: nowrap;
}

.lignes-tableau tbody tr:last-child > * {
    border-bottom: 0;
}

.lignes-tableau tbody tr:not(.lignes-edition):hover {
    background: #fbfcfd;
}

.lignes-ordre {
    color: var(--texte-secondaire);
    font-variant-numeric: tabular-nums;
    width: 4.5rem;
}

.lignes-intitule {
    display: grid;
    font-weight: 400;
    gap: 0.1rem;
}

.lignes-intitule strong {
    color: var(--texte);
    font-weight: 700;
}

.lignes-intitule span {
    color: var(--texte-secondaire);
    font-size: var(--texte-xs);
}

.lignes-intitule .lignes-badge {
    background: #eef6f8;
    border: 1px solid #b9dbe3;
    border-radius: 0.3rem;
    color: var(--action-survol);
    font-weight: 600;
    justify-self: start;
    margin-top: 0.3rem;
    padding: 0.1rem 0.4rem;
}

.lignes-horaire {
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
}

.lignes-action {
    text-align: right;
    white-space: nowrap;
    width: 1%;
}

.lignes-ligne-active > * {
    background: #f4f9fb;
    border-bottom-color: transparent !important;
}

.lignes-edition > td {
    background: #f4f9fb;
    padding: 0.25rem 1rem 1.25rem;
}

.lignes-edition-titre {
    font-size: var(--texte-m);
    margin: 0.75rem 0 0.25rem;
}

.lignes-vide {
    color: var(--texte-secondaire);
    padding: 1.5rem 1rem !important;
    text-align: center !important;
}


/* Formulaire ------------------------------------------------------------ */

.lignes-formulaire {
    background: #ffffff;
    border: 1px solid #e1e5e8;
    border-radius: 0.65rem;
    margin-top: 0.75rem;
    padding: 1rem 1.1rem;
}

.lignes-formulaire-grille {
    align-items: start;
    display: grid;
    gap: 1rem 1.25rem;
    grid-template-columns: minmax(16rem, 2fr) minmax(12rem, 1fr) auto 7rem;
}

.lignes-formulaire .champ {
    margin: 0;
}

.lignes-formulaire label,
.lignes-formulaire legend {
    color: var(--texte);
    display: block;
    font-size: var(--texte-s);
    font-weight: 600;
    margin-bottom: 0.35rem;
    padding: 0;
}

.lignes-formulaire textarea {
    min-height: 5.5rem;
    width: 100%;
}

.lignes-formulaire select,
.lignes-formulaire input[type="number"] {
    width: 100%;
}

.lignes-champ-intitule {
    grid-row: span 2;
}

.lignes-horaires {
    align-items: end;
    border: 0;
    display: flex;
    gap: 0.5rem;
    margin: 0;
    min-width: 0;
    padding: 0;
}

.lignes-horaires label {
    color: var(--texte-secondaire);
    font-size: var(--texte-xs);
    font-weight: 600;
}

.lignes-horaires > span {
    color: var(--texte-secondaire);
    padding-bottom: 0.7rem;
}

.lignes-jours,
.lignes-sans-personne {
    border: 0;
    grid-column: 2 / -1;
    margin: 0;
    min-width: 0;
    padding: 0;
}

.lignes-jours-options {
    display: flex;
    flex-wrap: wrap;
    gap: 0.4rem;
}

.lignes-formulaire .role-option {
    font-size: var(--texte-s);
    margin: 0;
    min-height: 2.25rem;
}

.lignes-sans-personne {
    align-items: center;
    display: flex;
    flex-wrap: wrap;
    gap: 0.4rem 0.75rem;
    grid-column: 1 / -1;
}

.lignes-sans-personne .aide {
    margin: 0;
}

.lignes-formulaire-actions {
    align-items: center;
    border-top: 1px solid #edf0f2;
    display: flex;
    gap: 1rem;
    margin-top: 1rem;
    padding-top: 1rem;
}

.lignes-cloture {
    align-items: center;
    display: flex;
    flex-wrap: wrap;
    gap: 0.75rem 1rem;
    justify-content: space-between;
    margin-top: 0.75rem;
    padding: 0 0.1rem;
}

.lignes-cloture label {
    align-items: flex-start;
    color: var(--texte-secondaire);
    display: flex;
    flex: 1 1 24rem;
    font-size: var(--texte-s);
    gap: 0.5rem;
}

.lignes-cloture input {
    margin-top: 0.2rem;
}

@media (max-width: 75rem) {
    .lignes-formulaire-grille {
        grid-template-columns: 1fr 1fr;
    }

    .lignes-champ-intitule,
    .lignes-jours {
        grid-column: 1 / -1;
        grid-row: auto;
    }
}

@media (max-width: 44rem) {
    .lignes-entete {
        align-items: stretch;
        flex-direction: column;
    }

    .lignes-formulaire-grille {
        grid-template-columns: 1fr;
    }
}
