#!/usr/bin/env php
<?php

declare(strict_types=1);

require_once __DIR__ . '/../src/autochargement.php';

use Garde\Controller\ControleurLignes;
use Garde\Http\Routeur;
use Garde\Repository\LignesGarde;
use Garde\Repository\PlanningHebdomadaire;
use Garde\Security\Jeton;
use Garde\Security\Role;
use Garde\Security\Utilisateur;
use Garde\Support\Base;
use Garde\Support\ErreurSaisie;

$base = Base::connexion();
Jeton::valeur();

$reussis = 0;
$echoues = 0;
/** @var list<string> $details */
$details = [];

function titre(string $texte): void
{
    echo PHP_EOL . $texte . PHP_EOL . str_repeat('-', strlen($texte)) . PHP_EOL;
}

function accepte(string $intitule, callable $cas): void
{
    global $reussis, $echoues, $details;

    try {
        $cas();
        $reussis++;
        printf("  ok       %s\n", $intitule);
    } catch (Throwable $erreur) {
        $echoues++;
        $details[] = $intitule . ' — ' . $erreur->getMessage();
        printf("  ECHEC    %s\n", $intitule);
    }
}

function refuse(string $intitule, callable $cas, string $erreurAttendue): void
{
    global $reussis, $echoues, $details;

    try {
        $cas();
        $echoues++;
        $details[] = $intitule . ' — accepté alors qu’il devait être refusé';
        printf("  ECHEC    %s  (accepté à tort)\n", $intitule);
    } catch (Throwable $erreur) {
        if ($erreur instanceof $erreurAttendue) {
            $reussis++;
            printf("  ok       %s\n", $intitule);
            return;
        }

        $echoues++;
        $details[] = $intitule . ' — erreur inattendue : ' . $erreur->getMessage();
        printf("  ECHEC    %s\n", $intitule);
    }
}

function verifier(bool $condition, string $message): void
{
    if (!$condition) {
        throw new RuntimeException($message);
    }
}

$marqueur = 'ZZLIGNE' . random_int(100000, 999999);

$creerUtilisateur = static function (string $suffixe, Role $role) use ($base, $marqueur): Utilisateur {
    $login = strtolower($marqueur . $suffixe);
    $base->prepare('INSERT INTO utilisateur (login, nom) VALUES (?, ?)')
        ->execute([$login, 'Compte ' . $suffixe]);
    $id = (int) $base->lastInsertId();
    $base->prepare('INSERT INTO utilisateur_role (utilisateur_id, role) VALUES (?, ?)')
        ->execute([$id, $role->value]);

    return Utilisateur::parLogin($base, $login);
};

$administrateur = $creerUtilisateur('-admin', Role::Administrateur);
$affairesMedicales = $creerUtilisateur('-am', Role::AffairesMedicales);
$consultation = $creerUtilisateur('-consultation', Role::Consultation);
$utilisateurIds = [$administrateur->id, $affairesMedicales->id, $consultation->id];

// Deux semaines de test loin dans le futur : un brouillon, et une semaine
// publiée dont la copie ne doit jamais bouger.
$vendredi = static function (int $decalageSemaines): string {
    $depart = new DateTimeImmutable('2091-01-05'); // un vendredi
    return $depart->modify('+' . (7 * $decalageSemaines) . ' days')->format('Y-m-d');
};
$semaineAleatoire = random_int(0, 400);
$brouillonId = PlanningHebdomadaire::creer($base, $affairesMedicales, $vendredi($semaineAleatoire));
$publieId = PlanningHebdomadaire::creer($base, $affairesMedicales, $vendredi($semaineAleatoire + 1));
$planningIds = [$brouillonId, $publieId];

$saisie = [
    'intitule' => "SMUR $marqueur\n  jour  ",
    'nature' => 'astreinte_domicile',
    'heure_debut' => '08:30',
    'heure_fin' => '20:30',
    'jours' => ['0', '1', '2', '3', '4'],
    'ordre' => '9990',
];

$copie = static function (int $planningId, int $modeleId) use ($base): array|false {
    $requete = $base->prepare(
        'SELECT intitule, nature, heure_debut, heure_fin, jours_application,
                sans_personne_nommee, ordre
           FROM ligne_planning
          WHERE planning_id = ? AND modele_ligne_id = ?'
    );
    $requete->execute([$planningId, $modeleId]);

    return $requete->fetch();
};

titre('Lignes de garde — modèle et semaines (EF-13, EF-14)');

$ligneId = 0;

accepte(
    'une ligne créée rejoint les brouillons avec sa définition complète',
    static function () use ($base, $administrateur, $saisie, $brouillonId, $publieId, $copie, &$ligneId, $marqueur): void {
        // La seconde semaine est publiée avant la création : elle ne doit pas
        // recevoir la nouvelle ligne.
        $base->prepare("UPDATE planning SET statut = 'publie' WHERE id = ?")->execute([$publieId]);
        $ligneId = LignesGarde::creer($base, $administrateur, $saisie);

        $ligne = LignesGarde::lire($base, $ligneId);
        verifier($ligne !== null, 'ligne absente du modèle');
        verifier($ligne['intitule'] === "SMUR $marqueur\njour", 'intitulé non normalisé');
        verifier($ligne['jours_application'] === '1111100', 'jours mal enregistrés');

        $dansBrouillon = $copie($brouillonId, $ligneId);
        verifier($dansBrouillon !== false, 'ligne absente du brouillon');
        verifier($dansBrouillon['nature'] === 'astreinte_domicile', 'nature non recopiée');
        verifier($dansBrouillon['heure_debut'] === '08:30:00', 'horaire non recopié');
        verifier($copie($publieId, $ligneId) === false, 'ligne ajoutée à une semaine publiée');
    },
);

accepte(
    'une modification suit dans les brouillons et est journalisée',
    static function () use ($base, $administrateur, $saisie, $brouillonId, $copie, &$ligneId): void {
        $modifie = LignesGarde::modifier($base, $administrateur, $ligneId, [
            'heure_debut' => '20:30',
            'heure_fin' => '08:30',
            'sans_personne_nommee' => '1',
        ] + $saisie);
        verifier($modifie, 'modification non détectée');

        $dansBrouillon = $copie($brouillonId, $ligneId);
        verifier($dansBrouillon['heure_debut'] === '20:30:00', 'brouillon non mis à jour');
        verifier((int) $dansBrouillon['sans_personne_nommee'] === 1, 'RG-15 non recopié');

        verifier(
            !LignesGarde::modifier($base, $administrateur, $ligneId, [
                'heure_debut' => '20:30',
                'heure_fin' => '08:30',
                'sans_personne_nommee' => '1',
            ] + $saisie),
            'un enregistrement sans changement est compté comme une modification',
        );

        $journal = $base->prepare(
            "SELECT COUNT(*) FROM journal_audit
              WHERE action = 'modification_ligne_garde' AND cible_id = ?"
        );
        $journal->execute([$ligneId]);
        verifier((int) $journal->fetchColumn() === 1, 'modification non journalisée une seule fois');
    },
);

accepte(
    'une nouvelle semaine recopie horaires, nature et jours du modèle',
    static function () use ($base, $affairesMedicales, $vendredi, $semaineAleatoire, $copie, &$ligneId, &$planningIds): void {
        $id = PlanningHebdomadaire::creer($base, $affairesMedicales, $vendredi($semaineAleatoire + 2));
        $planningIds[] = $id;

        $ligne = $copie($id, $ligneId);
        verifier($ligne !== false, 'ligne absente de la nouvelle semaine');
        verifier($ligne['heure_debut'] === '20:30:00', 'horaire non recopié à la création');
        verifier($ligne['nature'] === 'astreinte_domicile', 'nature non recopiée à la création');
        verifier($ligne['jours_application'] === '1111100', 'jours non recopiés à la création');
    },
);

refuse(
    'une ligne sans aucun jour d’application est refusée',
    static fn() => LignesGarde::creer($base, $administrateur, ['jours' => []] + $saisie),
    ErreurSaisie::class,
);

refuse(
    'une heure mal formée est refusée',
    static fn() => LignesGarde::creer($base, $administrateur, ['heure_fin' => '25:00'] + $saisie),
    ErreurSaisie::class,
);

refuse(
    'une nature inconnue est refusée',
    static fn() => LignesGarde::creer($base, $administrateur, ['nature' => 'vacation'] + $saisie),
    ErreurSaisie::class,
);

accepte(
    'une ligne clôturée quitte les brouillons et reste dans les semaines publiées',
    static function () use ($base, $administrateur, $brouillonId, $publieId, $copie, &$ligneId): void {
        // La semaine publiée reçoit sa copie comme si elle avait été publiée
        // avec cette ligne.
        $base->prepare(
            'INSERT INTO ligne_planning (planning_id, modele_ligne_id, intitule, ordre)
             SELECT ?, id, intitule, ordre FROM modele_ligne WHERE id = ?'
        )->execute([$publieId, $ligneId]);

        LignesGarde::cloturer($base, $administrateur, $ligneId);

        verifier(LignesGarde::lire($base, $ligneId) === null, 'ligne encore au modèle');
        verifier($copie($brouillonId, $ligneId) === false, 'ligne encore dans le brouillon');

        $publiee = $base->prepare(
            'SELECT COUNT(*) FROM ligne_planning WHERE planning_id = ? AND modele_ligne_id IS NULL'
        );
        $publiee->execute([$publieId]);
        verifier((int) $publiee->fetchColumn() >= 1, 'copie publiée effacée');
    },
);

titre('Droits (§ 6, EX-19)');

accepte(
    'les affaires médicales consultent les lignes sans pouvoir les modifier',
    static function () use ($base, $affairesMedicales, $consultation): void {
        $routeur = new Routeur();
        (new ControleurLignes($base, $routeur))->enregistrerRoutes();

        $page = $routeur->traiter('GET', '/lignes', $affairesMedicales);
        verifier($page['statut'] === 200, 'lecture refusée aux affaires médicales');
        verifier(!str_contains($page['contenu'], 'action="/lignes/enregistrer"'), 'formulaire proposé en lecture seule');
        verifier(
            $routeur->traiter('POST', '/lignes/enregistrer', $affairesMedicales)['statut'] === 403,
            'écriture autorisée aux affaires médicales',
        );
        verifier(
            $routeur->traiter('POST', '/lignes/cloturer', $affairesMedicales)['statut'] === 403,
            'clôture autorisée aux affaires médicales',
        );
        verifier(
            $routeur->traiter('GET', '/lignes', $consultation)['statut'] === 403,
            'lignes visibles en consultation',
        );
    },
);

accepte(
    'l’administrateur ouvre le formulaire sans JavaScript',
    static function () use ($base, $administrateur): void {
        $routeur = new Routeur();
        (new ControleurLignes($base, $routeur))->enregistrerRoutes();

        $_GET = ['nouvelle' => '1'];
        try {
            $page = $routeur->traiter('GET', '/lignes', $administrateur);
        } finally {
            $_GET = [];
        }
        verifier($page['statut'] === 200, 'page indisponible');
        verifier(str_contains($page['contenu'], 'action="/lignes/enregistrer"'), 'formulaire absent');
        verifier(str_contains($page['contenu'], 'name="jours[]"'), 'jours d’application absents');
        verifier(str_contains($page['contenu'], 'name="sans_personne_nommee"'), 'option RG-15 absente');
    },
);

// ---------------------------------------------------------------------
// Nettoyage
// ---------------------------------------------------------------------

$base->prepare('DELETE FROM ligne_planning WHERE intitule LIKE ?')->execute(["%$marqueur%"]);
$base->prepare('DELETE FROM modele_ligne WHERE intitule LIKE ?')->execute(["%$marqueur%"]);
$marqueurs = implode(',', array_fill(0, count($planningIds), '?'));
$base->prepare("DELETE FROM planning WHERE id IN ($marqueurs)")->execute($planningIds);
$marqueurs = implode(',', array_fill(0, count($utilisateurIds), '?'));
$base->prepare("DELETE FROM journal_audit WHERE utilisateur_id IN ($marqueurs)")->execute($utilisateurIds);
$base->prepare("DELETE FROM utilisateur_role WHERE utilisateur_id IN ($marqueurs)")->execute($utilisateurIds);
$base->prepare("DELETE FROM utilisateur WHERE id IN ($marqueurs)")->execute($utilisateurIds);

echo PHP_EOL . str_repeat('=', 58) . PHP_EOL;
printf(
    "%d vérifications, %d réussies, %d en échec\n",
    $reussis + $echoues,
    $reussis,
    $echoues,
);
foreach ($details as $detail) {
    echo '  - ' . $detail . PHP_EOL;
}

exit($echoues === 0 ? 0 : 1);

