/* =====================================================================
 * Planning — saisie / direction SaaS
 * ===================================================================== */


/* ---------------------------------------------------------------------
 * Commandes du planning
 * --------------------------------------------------------------------- */

.planning-commandes {
    /* Aligné sur le bas : le bouton de création tombe sur la même ligne
     * que le sélecteur de semaine, et non à hauteur de son libellé. */
    align-items: flex-end;
    display: flex;
    gap: 0.75rem;
    justify-content: space-between;
    margin-bottom: 1rem;
}

.planning-selecteur {
    align-items: end;
    display: flex;
    flex: 1 1 auto;
    gap: 0.55rem;
    max-width: 46rem;
}

.planning-selecteur-champ {
    flex: 1 1 auto;
}

.planning-selecteur label,
.planning-champ label {
    color: var(--texte-secondaire);
    display: block;
    font-size: var(--texte-xs);
    font-weight: 600;
    margin-bottom: 0.3rem;
}

.planning-selecteur select,
.planning-champ select {
    background: #ffffff;
    border: 1px solid #c9d0d4;
    border-radius: 0.35rem;
    color: var(--texte);
    font-size: var(--texte-s);
    height: 2.4rem;
    padding: 0 0.65rem;
}

.planning-afficher {
    background: #ffffff;
    border: 1px solid #cdd3d7;
    border-radius: 0.35rem;
    color: var(--texte);
    font-size: var(--texte-xs);
    font-weight: 600;
    height: 2.4rem;
    padding-inline: 0.8rem;
}

.planning-afficher:hover {
    background: #f5f7f8;
    border-color: #aeb8bd;
    color: var(--texte);
}


/* ---------------------------------------------------------------------
 * Création semaine
 * --------------------------------------------------------------------- */

.planning-creation {
    flex: 0 0 auto;

