// EF-22 : avertir avant de quitter l'écran avec une saisie non enregistrée.
//
// Seuls les formulaires marqués data-avertir-quitter sont suivis : une
// recherche ou un choix de semaine n'est pas une saisie qu'on perd. Une
// saisie est « en cours » dès que l'utilisateur modifie un champ, et cesse
// de l'être à l'envoi du formulaire. Sans JavaScript, rien ne prévient,
// mais rien n'empêche non plus d'enregistrer.

const enCours = new Set();

for (const formulaire of document.querySelectorAll('form[data-avertir-quitter]')) {
  formulaire.addEventListener('input', () => enCours.add(formulaire));
  formulaire.addEventListener('change', () => enCours.add(formulaire));
  formulaire.addEventListener('reset', () => enCours.delete(formulaire));
  // Tout envoi quitte la page volontairement, y compris un autre
  // formulaire de la même page (« Retirer la personne »).
  document.addEventListener('submit', () => enCours.clear(), true);
}

window.addEventListener('beforeunload', (evenement) => {
  // Un formulaire retiré ou masqué par un script (panneau refermé) ne
  // retient plus personne.
  for (const formulaire of enCours) {
    if (!formulaire.isConnected || formulaire.closest('[hidden]') !== null) {
      enCours.delete(formulaire);
    }
  }
  if (enCours.size > 0) {
    evenement.preventDefault();
    // Le texte est imposé par le navigateur ; la valeur doit seulement
    // être non vide pour les navigateurs anciens.
    evenement.returnValue = '';
  }
});

