<?php
declare(strict_types=1);
namespace Garde\Service;
use DateTimeImmutable;
use PDO;
/**
 * Qui est joignable à cet instant (CDC § 8.6).
 *
 * C'est l'écran le plus important de l'application. Quand un service demande
 * le réanimateur de garde à 3 h du matin, c'est ici que le numéro est
 * cherché. Une erreur ne se traduit pas par une gêne administrative mais par
 * un appel perdu en pleine nuit.
 *
 * Trois conséquences sur le code :
 *
 *   - les numéros sont lus au moment de l'affichage, jamais recopiés
 *     (RG-07) : une correction du standard vaut immédiatement ;
 *   - une ligne applicable et non pourvue est retournée explicitement,
 *     jamais omise (RG-12) — une absence silencieuse se lit « il n'y a
 *     personne », ce qui est faux et dangereux ;
 *   - l'instant de référence est un paramètre, pas un appel à l'horloge
 *     enfoui : sans cela, le comportement à la bascule de 8h30 ou de minuit
 *     n'est pas vérifiable.
 */
final class DeGardeMaintenant
{
    /**
     * Lignes en cours à l'instant donné.
     *
     * Une garde qui commence à 18h30 et finit à 8h30 court sur deux dates.
     * On examine donc la veille, le jour même et le lendemain, et l'on
     * retient les plages qui encadrent réellement l'instant.
     *
     * @return list<array<string, mixed>>
     */
    public static function enCours(PDO $base, DateTimeImmutable $instant): array
    {
        return self::lire($base, [
            $instant->modify('-1 day')->format('Y-m-d'),
            $instant->format('Y-m-d'),
            $instant->modify('+1 day')->format('Y-m-d'),
        ], $instant);
    }
