/** @param array<string, mixed> $donnees */
public static function modifier(
    PDO $base,
    Utilisateur $acteur,
    int $id,
    array $donnees,
    bool $homonymieConfirmee = false,
): bool {
    $personne = self::nettoyer($donnees);
    $base->beginTransaction();

    try {
        $existante = self::verrouiller($base, $id);
        self::verifierReferences($base, $personne);

        $identiteChangee = $existante['nom_recherche'] !== $personne['nom_recherche']
            || $existante['prenom_recherche'] !== $personne['prenom_recherche']
            || ($existante['service_id'] === null
                ? $personne['service_id'] !== null
                : (int) $existante['service_id'] !== $personne['service_id']);

        $discriminant = (int) $existante['discriminant'];
        if ($identiteChangee) {
            $homonymes = self::homonymes(
                $base,
                $personne['nom_recherche'],
                $personne['prenom_recherche'],
                $personne['service_id'],
                $id,
            );
            if ($homonymes !== [] && !$homonymieConfirmee) {
                throw new HomonymieAConfirmer($homonymes);
            }
            $discriminant = $homonymes === []
                ? 0
                : self::prochainDiscriminant($base, $personne);
        }

        $avant = self::instantane($existante);
        $apres = [
            'civilite' => $personne['civilite'],
            'nom' => $personne['nom'],
            'prenom' => $personne['prenom'],
            'profession_id' => $personne['profession_id'],
            'specialite_id' => $personne['specialite_id'],
            'service_id' => $personne['service_id'],
            'discriminant' => $discriminant,
            'actif' => (bool) $existante['actif'],
            'date_fin_activite' => $existante['date_fin_activite'],
        ];

        if ($avant === $apres) {
            $base->commit();
            return false;
        }

        $requete = $base->prepare(
            'UPDATE personne
                SET civilite = ?, nom = ?, nom_recherche = ?,
                    prenom = ?, prenom_recherche = ?, profession_id = ?,
                    specialite_id = ?, service_id = ?, discriminant = ?
              WHERE id = ?'
        );
        $requete->execute([
            $personne['civilite'],
            $personne['nom'],
            $personne['nom_recherche'],
            $personne['prenom'],
            $personne['prenom_recherche'],
            $personne['profession_id'],
            $personne['specialite_id'],
            $personne['service_id'],
            $discriminant,
            $id,
        ]);

        Journal::consigner(
