    {
        try {
            $id = $this->identifiant($_POST['id'] ?? null, 'La personne demandée');
            if (($_POST['confirmer_suppression'] ?? null) !== '1') {
                throw new ErreurSaisie(
                    'Vous devez confirmer explicitement la suppression définitive.'
                );
            }
            ReferentielPersonnes::supprimer($this->base, $utilisateur, $id);
        } catch (ErreurSaisie $erreur) {
            return $this->erreur(
                400,
                'Suppression impossible',
                $erreur->getMessage() . ' Revenez à la fiche et choisissez '
                    . 'l’action appropriée.',
                $utilisateur,
            );
        }

        return $this->redirection('/personnes?etat=supprime');
    }

    /** @return array{statut: int, contenu: string} */
    public function coordonnees(Utilisateur $utilisateur): array
    {
        $recherche = $this->recherche();
        $personnes = ReferentielPersonnes::lister(
            $this->base,
            $recherche,
            false,
            true,
        );
        $this->journaliserConsultationNumeros(
            $utilisateur,
            'coordonnees',
            null,
            $personnes,
        );

        return $this->page('personnes/coordonnees', [
            'titrePage' => 'Coordonnées téléphoniques',
            'cheminCourant' => '/coordonnees',
            'personnes' => $personnes,

