                    value="<?= Gabarit::echapper($recherche) ?>"
                    autocomplete="off"
                    placeholder="Rechercher une personne ou un numéro…"
                    data-champ-recherche
                >

                <button type="submit">
                    Rechercher
                </button>
            </div>

            <output
                class="coordonnees-resultats"
                data-resultats-recherche
