14	/**
15	 * Santé technique (CDC EF-55).
16	 *
17	 * Quatre indicateurs, choisis parce que chacun annonce un appel perdu :
18	 * une base injoignable, une semaine qui n'a pas été publiée, une personne
19	 * qu'on ne peut pas appeler, une garde sans personne. La page n'écrit rien.
20	 */
21	final class ControleurSante
22	{
23	    public function __construct(
24	        private readonly PDO $base,
25	        private readonly Routeur $routeur,
26	    ) {
27	    }
28	
29	    public function enregistrerRoutes(): void
30	    {
31	        $this->routeur->ajouter('GET', '/sante', [Role::Administrateur], [$this, 'afficher']);
32	    }
33	
34	    /** @return array{statut: int, contenu: string} */
35	    public function afficher(Utilisateur $utilisateur): array
36	    {
37	        // L'heure de la base, et non celle de PHP : c'est la preuve que la
38	        // requête est bien allée jusqu'à elle.
39	        $heureBase = (string) $this->base->query('SELECT NOW()')->fetchColumn();
40	
41	        $publication = $this->base->query(
42	            "SELECT p.libelle, p.date_debut, p.publie_le, u.login
43	               FROM planning p
44	          LEFT JOIN utilisateur u ON u.id = p.publie_par_id
45	              WHERE p.statut = 'publie'
46	           ORDER BY p.publie_le DESC
47	              LIMIT 1"
48	        )->fetch() ?: null;
49	
50	        $sansNumero = (int) $this->base->query(
51	            'SELECT COUNT(*) FROM personne p
52	              WHERE p.actif = 1
53	                AND NOT EXISTS (SELECT 1 FROM telephone t WHERE t.personne_id = p.id)'
54	        )->fetchColumn();
55	
56	        $semaineCouverte = [];
57	        $nonPourvues = 0;
58	        $aujourdhui = new DateTimeImmutable('today');
59	        $detail = [];
60	        for ($decalage = 0; $decalage < 7; $decalage++) {
61	            $jour = $aujourdhui->modify('+' . $decalage . ' days');
62	            $cases = $this->nonPourvues($jour);
63	            $detail[] = [
64	                'jour' => $jour,
65	                'semaine' => $cases['semaine'],
66	                'non_pourvues' => $cases['non_pourvues'],
67	            ];
68	            if ($cases['semaine'] !== null) {
69	                $semaineCouverte[] = $jour;
70	                $nonPourvues += $cases['non_pourvues'];
71	            }
72	        }
73	
74	        // EF-28 : qui a publié ou retiré quelle semaine, et quand. Lu dans
75	        // le journal, seul à garder toutes les publications successives
76	        // d'une même semaine (planning ne retient que la dernière).
77	        $publications = $this->base->query(
78	            "SELECT j.horodatage, j.login, j.action, p.libelle, p.date_debut
79	               FROM journal_audit j
80	          LEFT JOIN planning p ON p.id = j.cible_id
81	              WHERE j.action IN ('publication_semaine', 'depublication_semaine')
82	           ORDER BY j.horodatage DESC, j.id DESC
83	              LIMIT 20"
84	        )->fetchAll();
85	
86	        return [
87	            'statut' => 200,
88	            'contenu' => Gabarit::rendre('administration/sante', [
89	                'publications' => $publications,
90	                'titrePage' => 'Santé technique',
91	                'utilisateur' => $utilisateur,
92	                'routeur' => $this->routeur,
93	                'cheminCourant' => '/sante',
94	                'heureBase' => $heureBase,
95	                'publication' => $publication,
96	                'sansNumero' => $sansNumero,
97	                'nonPourvues' => $nonPourvues,
98	                'joursSansSemaine' => 7 - count($semaineCouverte),
99	                'detail' => $detail,
100	            ]),
101	        ];
102	    }
103	
104	    /**
105	     * Cases non pourvues d'un jour (RG-12) : lignes qui s'appliquent ce
106	     * jour-là, n'attendent pas « sans personne nommée » (RG-15), et n'ont
107	     * aucune affectation. Semaine publiée de préférence, sinon brouillon.
108	     *
109	     * @return array{semaine: ?array<string, mixed>, non_pourvues: int}
110	     */
111	    private function nonPourvues(DateTimeImmutable $jour): array
112	    {
113	        $date = $jour->format('Y-m-d');
114	        $requete = $this->base->prepare(
115	            "SELECT id, libelle, statut FROM planning
116	              WHERE ? BETWEEN date_debut AND date_fin
117	           ORDER BY statut = 'publie' DESC
118	              LIMIT 1"
119	        );
120	        $requete->execute([$date]);
121	        $semaine = $requete->fetch();
122	        if ($semaine === false) {
123	            return ['semaine' => null, 'non_pourvues' => 0];
124	        }
125	
126	        // jours_application commence au lundi : rang 1 à 7 = N de PHP.
127	        $rang = (int) $jour->format('N');
128	        $requete = $this->base->prepare(
129	            'SELECT COUNT(*) FROM ligne_planning l
130	              WHERE l.planning_id = ?
131	                AND l.sans_personne_nommee = 0
132	                AND SUBSTRING(l.jours_application, ?, 1) = \'1\'
133	                AND NOT EXISTS (
134	                    SELECT 1 FROM affectation_planning a
135	                     WHERE a.ligne_planning_id = l.id AND a.jour = ?
136	                )'
137	        );
138	        $requete->execute([(int) $semaine['id'], $rang, $date]);
139	
140	        return ['semaine' => $semaine, 'non_pourvues' => (int) $requete->fetchColumn()];
141	    }
142	}

