content.content:
.details-fiche {
    display: grid;
    gap: var(--pas-court) var(--pas);
    grid-template-columns: repeat(auto-fit, minmax(min(100%, 14rem), 1fr));
    margin: var(--pas) 0 var(--pas-long);
}

.details-fiche div {
    border-left: 0.25rem solid var(--bordure-fine);
    padding-left: 0.65rem;
}

.details-fiche dt {
    color: var(--texte-secondaire);
    font-size: var(--texte-s);
    font-weight: 700;
}

.details-fiche dd {
    margin: 0;
}

.liste-coordonnees {
    display: grid;
    gap: var(--pas-long);
}

.fiche-coordonnees {
    border: 1px solid var(--bordure-fine);
    border-left: 0.25rem solid var(--bordure);
    border-radius: var(--rayon-bloc);
    padding: var(--pas-long);
}

.fiche-coordonnees header h2 {
    margin-top: 0;
}

}

.confirmation,
.erreur-saisie,
.alerte,
.resume-anomalies {
    background: var(--fond-elevation);
    border: 1px solid var(--bordure-fine);
    border-left: 0.3rem solid var(--confirmation);
    border-radius: var(--rayon-controle);
    color: var(--texte);
    margin-bottom: var(--pas);
    padding: 0.75rem var(--pas);
}

.erreur-saisie,
.alerte {
    border-left-color: var(--erreur);
}

.alerte {
    font-weight: 400;
}


/*
 * Pas de gros fond vert / jaune.
 * L'état est indiqué avec une simple bordure latérale.
 */

.apercu-resume--complet {
    border-left: 3px solid #6e9c7d;
}

.apercu-resume--incomplet {
    border-left: 3px solid #a38c70;
}


